+
+module.exports = {
+	name: 'Rename object and sorted sets used in post uploads',
+	timestamp: Date.UTC(2022, 1, 10),
+
+	async method(context) {
+		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
+		const log = message => {
+			if (context && typeof context.log === 'function') {
+				context.log(message);
+			}
+		};
+		const updateProgress = (current, total) => {
+			if (context && typeof context.updateProgress === 'function') {
+				context.updateProgress(current, total);
+			}
+		};
+
+		// Collect all unique upload paths referenced by posts that lack the files/ prefix
+		const postUploadKeys = await db.scan({ match: 'post:*:uploads' });
+		const paths = new Set();
+		for (const key of postUploadKeys) {
+			/* eslint-disable no-await-in-loop */
+			const members = await db.getSortedSetMembers(key);
+			members.forEach(member => {
+				if (!member.startsWith('files/')) {
+					paths.add(member);
+				}
+			});
+		}
+
+		const allPaths = [...paths];
+		updateProgress(0, allPaths.length);
+		let current = 0;
+
+		// Rename the reverse-mapping sorted sets and size objects to use hashes of the prefixed paths
+		for (const filePath of allPaths) {
+			/* eslint-disable no-await-in-loop */
+			const oldHash = md5(filePath);
+			const newHash = md5(`files/${filePath}`);
+
+			// Merge the reverse-mapping sorted set into the new key
+			const oldPidsKey = `upload:${oldHash}:pids`;
+			const newPidsKey = `upload:${newHash}:pids`;
+			const pids = await db.getSortedSetRangeWithScores(oldPidsKey, 0, -1);
+			if (pids.length) {
+				await db.sortedSetAdd(newPidsKey, pids.map(p => p.score), pids.map(p => p.value));
+			}
+			await db.delete(oldPidsKey);
+
+			// Rename the size object
+			const oldObjectKey = `upload:${oldHash}`;
+			const newObjectKey = `upload:${newHash}`;
+			const object = await db.getObject(oldObjectKey);
+			if (object) {
+				await db.setObject(newObjectKey, object);
+			}
+			await db.delete(oldObjectKey);
+
+			current += 1;
+			updateProgress(current, allPaths.length);
+		}
+
+		// Update each post's uploads set to reference the prefixed paths
+		for (const key of postUploadKeys) {
+			/* eslint-disable no-await-in-loop */
+			const members = await db.getSortedSetRangeWithScores(key, 0, -1);
+			const prefixed = members.map(member => ({
+				value: member.value.startsWith('files/') ? member.value : `files/${member.value}`,
+				score: member.score,
+			}));
+			if (prefixed.some((member, idx) => member.value !== members[idx].value)) {
+				await db.sortedSetRemove(key, members.map(member => member.value));
+				await db.sortedSetAdd(key, prefixed.map(member => member.score), prefixed.map(member => member.value));
+			}
+		}
+
+		log(`Renamed ${allPaths.length} post upload hash(es)`);
+	},
+};

