+
+export interface KeyCombo {
+    key: string;
+    ctrlKey?: boolean;
+    altKey?: boolean;
+    shiftKey?: boolean;
+    metaKey?: boolean;
+    ctrlOrCmd?: boolean;
+}
+
+export function isKeyComboMatch(ev: KeyboardEvent | React.KeyboardEvent, combo: KeyCombo, onMac: boolean): boolean {
+    // Normalize the key
+    const key = ev.key.toLowerCase();
+    const comboKey = combo.key.toLowerCase();
+
+    // Check the key matches
+    if (key !== comboKey) {
+        return false;
+    }
+
+    // Check the modifiers match
+    const expectedCtrl = !!(combo.ctrlKey || (combo.ctrlOrCmd && !onMac));
+    const expectedCmd = !!(combo.metaKey || (combo.ctrlOrCmd && onMac));
+
+    if (ev.ctrlKey !== expectedCtrl) return false;
+    if (ev.metaKey !== expectedCmd) return false;
+    if (ev.altKey !== !!combo.altKey) return false;
+
+    // Shift key is special: if the combo requires shift, then shift must be pressed.
+    // If the combo doesn't require shift, then shift can be pressed for letter keys (because of capitalization).
+    if (combo.shiftKey) {
+        if (!ev.shiftKey) return false;
+    } else if (ev.shiftKey) {
+        // Shift is allowed for letter keys (e.g. pressing "A" instead of "a")
+        // but not for other keys
+        if (key.length !== 1 || (key < "a" || key > "z")) return false;
+    }
+
+    return true;
+}

