+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: DeviceWithVerification["device_id"], deviceName: string) => Promise<void>;
+}
+
+const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [editing, setEditing] = useState(false);
+    const [name, setName] = useState("");
+    const [saving, setSaving] = useState(false);
+    const [error, setError] = useState<string>();
+
+    const onRenameClick = () => {
+        setName(device.display_name ?? "");
+        setEditing(true);
+    };
+
+    const onSaveClick = async () => {
+        // only persist the name if it has changed
+        if (name === device.display_name) {
+            setEditing(false);
+            return;
+        }
+        setSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, name);
+            setEditing(false);
+        } catch (e) {
+            setError(_t("Failed to set display name."));
+        } finally {
+            setSaving(false);
+        }
+    };
+
+    const onCancelClick = () => {
+        setEditing(false);
+        setError(undefined);
+    };
+
+    if (editing) {
+        return <div className="mx_DeviceDetailHeading" data-testid="device-detail-heading-edit">
+            <Field
+                value={name}
+                onChange={(e) => setName(e.target.value)}
+                placeholder={_t("Name this session")}
+                maxLength={100}
+                autoFocus
+                data-testid="device-detail-heading-edit-input"
+            />
+            <p className="mx_DeviceDetailHeading_description">
+                { _t("Session names are visible to other people you communicate with.") }
+            </p>
+            { error && <p className="mx_DeviceDetailHeading_error">{ error }</p> }
+            <AccessibleButton
+                kind="primary"
+                onClick={onSaveClick}
+                disabled={saving}
+                data-testid="device-detail-heading-edit-save"
+            >
+                { saving ? _t("Saving…") : _t("Save") }
+            </AccessibleButton>
+            <AccessibleButton
+                kind="link"
+                onClick={onCancelClick}
+                disabled={saving}
+                data-testid="device-detail-heading-edit-cancel"
+            >
+                { _t("Cancel") }
+            </AccessibleButton>
+        </div>;
+    }
+
+    return <div className="mx_DeviceDetailHeading" data-testid="device-detail-heading">
+        <Heading size="h3">{ device.display_name ?? device.device_id }</Heading>
+        <AccessibleButton
+            kind="link_inline"
+            onClick={onRenameClick}
+            data-testid="device-detail-heading-rename"
+        >
+            { _t("Rename") }
+        </AccessibleButton>
+    </div>;
+};
+
+export { DeviceDetailHeading };
+export default DeviceDetailHeading;
