+
+import { useCallback, useEffect, useState } from "react";
+
+import UIStore, { UI_EVENTS } from "../stores/UIStore";
+
+/**
+ * Hook to track the current window width.
+ *
+ * Returns the current window width from the UIStore, and updates the value
+ * whenever the UIStore emits a resize event.
+ *
+ * @returns The current window width in pixels.
+ */
+export function useWindowWidth(): number {
+    const [windowWidth, setWindowWidth] = useState<number>(() => UIStore.instance.windowWidth);
+
+    const onResize = useCallback(() => {
+        setWindowWidth(UIStore.instance.windowWidth);
+    }, []);
+
+    useEffect(() => {
+        UIStore.instance.on(UI_EVENTS.Resize, onResize);
+        return () => {
+            UIStore.instance.off(UI_EVENTS.Resize, onResize);
+        };
+    }, [onResize]);
+
+    return windowWidth;
+}

