new file mode 100644
index 0000000000..65c43ca266
--- /dev/null
+++ b/src/components/views/rooms/EventPreview.tsx
@@ -0,0 +1,135 @@
+/*
+ * Copyright 2024 New Vector Ltd.
+ * Copyright 2024 The Matrix.org Foundation C.I.C.
+ *
+ * SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+ * Please see LICENSE files in the repository root for full details.
+ */
+
+import React, { HTMLAttributes, JSX, useContext, useMemo, useState } from "react";
+import { IContent, MatrixEvent, MatrixEventEvent, M_POLL_START, MsgType } from "matrix-js-sdk/src/matrix";
+import classNames from "classnames";
+
+import { _t } from "../../../languageHandler";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import { useTypedEventEmitter } from "../../../hooks/useEventEmitter";
+import MatrixClientContext from "../../../contexts/MatrixClientContext";
+
+/**
+ * A preview of an event, with an optional prefix.
+ */
+export type Preview = [preview: string, prefix: string | null];
+
+/**
+ * The props for the {@link EventPreview} component.
+ */
+export interface IEventPreviewProps extends HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The event to preview
+     */
+    mxEvent: MatrixEvent;
+}
+
+/**
+ * A component to render a preview of an event.
+ * @param props - The props for the component.
+ * @returns The component.
+ */
+export function EventPreview({ mxEvent, className, ...props }: IEventPreviewProps): JSX.Element | null {
+    const preview = useEventPreview(mxEvent);
+    if (!preview) return null;
+
+    return <EventPreviewTile preview={preview} className={className} {...props} />;
+}
+
+/**
+ * The props for the {@link EventPreviewTile} component.
+ */
+export interface IEventPreviewTileProps extends HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The preview to render
+     */
+    preview: Preview;
+}
+
+/**
+ * A component to render a preview of an event with an optional prefix.
+ * @param props - The props for the component.
+ * @returns The component.
+ */
+export function EventPreviewTile({ preview, className, ...props }: IEventPreviewTileProps): JSX.Element | null {
+    const [previewText, prefix] = preview;
+    if (!previewText) return null;
+
+    return (
+        <span className={classNames("mx_EventPreview", className)} {...props}>
+            {prefix ? (
+                <>
+                    <span className="mx_EventPreview_prefix">{prefix}:</span> {previewText}
+                </>
+            ) : (
+                previewText
+            )}
+        </span>
+    );
+}
+
+/**
+ * A hook to generate a preview of an event.
+ * @param mxEvent - The event to generate a preview for.
+ * @returns The preview and prefix for the event, or null if no preview can be generated.
+ */
+export function useEventPreview(mxEvent: MatrixEvent | undefined): Preview | null {
+    const cli = useContext(MatrixClientContext);
+    // track the content as a means to regenerate the preview upon edits & decryption
+    const [content, setContent] = useState<IContent | undefined>(mxEvent?.getContent());
+    useTypedEventEmitter(mxEvent, MatrixEventEvent.Replaced, () => {
+        setContent(mxEvent!.getContent());
+    });
+    const awaitDecryption = mxEvent?.shouldAttemptDecryption() || mxEvent?.isBeingDecrypted();
+    useTypedEventEmitter(awaitDecryption ? mxEvent : undefined, MatrixEventEvent.Decrypted, () => {
+        setContent(mxEvent!.getContent());
+    });
+
+    const preview = useAsyncMemo(async (): Promise<string | undefined> => {
+        if (!mxEvent) return;
+        await cli?.decryptEventIfNeeded(mxEvent);
+        return MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+    }, [mxEvent, content]);
+
+    const prefix = useMemo(() => {
+        if (!mxEvent) return null;
+        return getPreviewPrefix(mxEvent.getType(), mxEvent.getContent().msgtype as MsgType);
+    }, [mxEvent, content]);
+
+    if (!preview) return null;
+    return [preview, prefix];
+}
+
+/**
+ * Get the prefix for the preview based on the type and the message type.
+ * @param type - The type of the event.
+ * @param msgType - The message type of the event.
+ * @returns The prefix for the preview, or null if no prefix is needed.
+ */
+function getPreviewPrefix(type: string, msgType: MsgType | undefined): string | null {
+    switch (type) {
+        case M_POLL_START.name:
+            return _t("event_preview|prefix|poll");
+        default:
+    }
+
+    switch (msgType) {
+        case MsgType.Audio:
+            return _t("event_preview|prefix|audio");
+        case MsgType.Image:
+            return _t("event_preview|prefix|image");
+        case MsgType.Video:
+            return _t("event_preview|prefix|video");
+        case MsgType.File:
+            return _t("event_preview|prefix|file");
+        default:
+            return null;
+    }
+}
