+
+import { MatrixClient, MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+import {
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "state_changed",
+}
+
+export interface VoiceBroadcastRecordingEmitter {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (
+        recording: VoiceBroadcastRecording,
+        state: VoiceBroadcastInfoState,
+    ) => void;
+}
+
+export class VoiceBroadcastRecording extends TypedEventEmitter<VoiceBroadcastRecordingEvent, VoiceBroadcastRecordingEmitter> {
+    private _state: VoiceBroadcastInfoState;
+
+    constructor(
+        private client: MatrixClient,
+        private infoEvent: MatrixEvent,
+        state: VoiceBroadcastInfoState,
+    ) {
+        super();
+        this._state = state;
+    }
+
+    public get state(): VoiceBroadcastInfoState {
+        return this._state;
+    }
+
+    public get id(): string {
+        return this.infoEvent.getId();
+    }
+
+    public get roomId(): string {
+        return this.infoEvent.getRoomId();
+    }
+
+    public async stop(): Promise<void> {
+        if (this.state === VoiceBroadcastInfoState.Stopped) {
+            return;
+        }
+
+        await this.client.sendStateEvent(
+            this.roomId,
+            VoiceBroadcastInfoEventType,
+            {
+                state: VoiceBroadcastInfoState.Stopped,
+                ["m.relates_to"]: {
+                    rel_type: RelationType.Reference,
+                    event_id: this.id,
+                },
+            },
+            this.client.getUserId(),
+        );
+
+        this._state = VoiceBroadcastInfoState.Stopped;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged, this, this._state);
+    }
+}
