+
+import { MatrixClient, MatrixEvent, Room, RoomEvent } from "matrix-js-sdk/src/matrix";
+
+import {
+    VoiceBroadcastInfoEventContent,
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+import { VoiceBroadcastRecordingsStore } from "../stores";
+
+export async function startNewVoiceBroadcastRecording(
+    client: MatrixClient,
+    roomId: string,
+): Promise<MatrixEvent> {
+    const content: VoiceBroadcastInfoEventContent = {
+        state: VoiceBroadcastInfoState.Started,
+        chunk_length: 300,
+    };
+
+    const room = client.getRoom(roomId);
+
+    const infoEvent = await new Promise<MatrixEvent>((resolve) => {
+        const onRoomTimeline = (event: MatrixEvent, timelineRoom: Room | null) => {
+            if (timelineRoom?.roomId !== roomId) {
+                return;
+            }
+
+            if (event.getType() !== VoiceBroadcastInfoEventType) {
+                return;
+            }
+
+            client.off(RoomEvent.Timeline, onRoomTimeline);
+            room?.off(RoomEvent.Timeline, onRoomTimeline);
+            resolve(event);
+        };
+
+        // The event may already be in the room state
+        const existingEvent = room?.getUnfilteredTimelineSet()?.getLiveTimeline()?.getEvents()
+            .find((event) => event.getType() === VoiceBroadcastInfoEventType);
+        if (existingEvent) {
+            resolve(existingEvent);
+            return;
+        }
+
+        client.on(RoomEvent.Timeline, onRoomTimeline);
+        room?.on(RoomEvent.Timeline, onRoomTimeline);
+
+        client.sendStateEvent(roomId, VoiceBroadcastInfoEventType, content, client.getUserId());
+    });
+
+    const recording = VoiceBroadcastRecordingsStore.instance.getOrCreateRecording(
+        client,
+        infoEvent,
+        VoiceBroadcastInfoState.Started,
+    );
+    VoiceBroadcastRecordingsStore.instance.setCurrent(recording);
+
+    return infoEvent;
+}

