+package kubernetes
+
+import (
+	"context"
+	"crypto/tls"
+	"crypto/x509"
+	"fmt"
+	"net/http"
+	"os"
+	"strings"
+	"time"
+
+	"github.com/coreos/go-oidc/v3/oidc"
+	"go.flipt.io/flipt/errors"
+	"go.flipt.io/flipt/internal/config"
+	storageauth "go.flipt.io/flipt/internal/storage/auth"
+	"go.flipt.io/flipt/rpc/flipt/auth"
+	"go.uber.org/zap"
+	"google.golang.org/grpc"
+	"google.golang.org/protobuf/types/known/timestamppb"
+)
+
+const (
+	storageMetadataKubernetesSubKey       = "io.flipt.auth.kubernetes.sub"
+	storageMetadataKubernetesUsernameKey  = "io.flipt.auth.kubernetes.username"
+	storageMetadataKubernetesNamespaceKey = "io.flipt.auth.kubernetes.namespace"
+
+	// defaultKubernetesCAPath is the default path to the CA certificate
+	// when running within a Kubernetes cluster.
+	defaultKubernetesCAPath = "/var/run/secrets/kubernetes.io/serviceaccount/ca.crt"
+
+	// defaultKubernetesServiceAccountTokenPath is the default path to the
+	// service account token when running within a Kubernetes cluster.
+	defaultKubernetesServiceAccountTokenPath = "/var/run/secrets/kubernetes.io/serviceaccount/token"
+)
+
+// Server is an implementation of auth.AuthenticationMethodKubernetesServiceServer.
+//
+// It is used to validate Kubernetes service account tokens against the
+// cluster's OIDC provider and create associated Flipt authentications.
+type Server struct {
+	logger *zap.Logger
+	store  storageauth.Store
+	config config.AuthenticationConfig
+
+	auth.UnimplementedAuthenticationMethodKubernetesServiceServer
+}
+
+// NewServer constructs and configures a new *Server.
+func NewServer(
+	logger *zap.Logger,
+	store storageauth.Store,
+	config config.AuthenticationConfig,
+) *Server {
+	return &Server{
+		logger: logger,
+		store:  store,
+		config: config,
+	}
+}
+
+// RegisterGRPC registers the server as a Server on the provided grpc server.
+func (s *Server) RegisterGRPC(server *grpc.Server) {
+	auth.RegisterAuthenticationMethodKubernetesServiceServer(server, s)
+}
+
+// Validate validates a Kubernetes service account token against the
+// configured cluster's OIDC provider.
+// Given the token is valid, an associated Flipt client token and
+// Authentication are created and returned.
+func (s *Server) Validate(ctx context.Context, req *auth.ValidateRequest) (*auth.ValidateResponse, error) {
+	cfg := s.config.Methods.Kubernetes.Method
+
+	token, err := s.token(req.GetToken(), cfg.ServiceAccountTokenPath)
+	if err != nil {
+		return nil, err
+	}
+
+	issuerURL, err := s.issuerURL(cfg.IssuerURL)
+	if err != nil {
+		return nil, err
+	}
+
+	caPath := cfg.CAPath
+	isDefaultCA := false
+	if caPath == "" {
+		caPath = defaultKubernetesCAPath
+		isDefaultCA = true
+	}
+
+	httpClient, err := s.httpClient(caPath, isDefaultCA)
+	if err != nil {
+		return nil, err
+	}
+
+	ctx = oidc.ClientContext(ctx, httpClient)
+
+	provider, err := oidc.NewProvider(ctx, issuerURL)
+	if err != nil {
+		return nil, fmt.Errorf("kubernetes: creating OIDC provider for issuer %q: %w", issuerURL, err)
+	}
+
+	verifier := provider.Verifier(&oidc.Config{
+		SkipClientIDCheck: true,
+	})
+
+	idToken, err := verifier.Verify(ctx, token)
+	if err != nil {
+		return nil, errors.ErrUnauthenticatedf("kubernetes: invalid service account token: %v", err)
+	}
+
+	var c claims
+	if err := idToken.Claims(&c); err != nil {
+		return nil, fmt.Errorf("kubernetes: parsing token claims: %w", err)
+	}
+
+	metadata := map[string]string{
+		storageMetadataKubernetesSubKey: c.Subject,
+	}
+	if c.Username != "" {
+		metadata[storageMetadataKubernetesUsernameKey] = c.Username
+	}
+	if c.Namespace != "" {
+		metadata[storageMetadataKubernetesNamespaceKey] = c.Namespace
+	}
+
+	clientToken, authentication, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
+		Method:    auth.Method_METHOD_KUBERNETES,
+		ExpiresAt: timestamppb.New(expiresAt(idToken, s.config.Session.TokenLifetime)),
+		Metadata:  metadata,
+	})
+	if err != nil {
+		return nil, fmt.Errorf("kubernetes: creating authentication: %w", err)
+	}
+
+	return &auth.ValidateResponse{
+		ClientToken:    clientToken,
+		Authentication: authentication,
+	}, nil
+}
+
+// token resolves the service account token to validate. It prefers the token
+// provided on the request, falling back to the configured (or default
+// in-cluster) service account token file.
+func (s *Server) token(provided, tokenPath string) (string, error) {
+	if provided != "" {
+		return provided, nil
+	}
+
+	if tokenPath == "" {
+		tokenPath = defaultKubernetesServiceAccountTokenPath
+	}
+
+	tokenBytes, err := os.ReadFile(tokenPath)
+	if err != nil {
+		return "", fmt.Errorf("kubernetes: reading service account token %q: %w", tokenPath, err)
+	}
+
+	return strings.TrimSpace(string(tokenBytes)), nil
+}
+
+// issuerURL resolves the cluster API server issuer URL, falling back to the
+// in-cluster environment variables when not explicitly configured.
+func (s *Server) issuerURL(configured string) (string, error) {
+	if configured != "" {
+		return configured, nil
+	}
+
+	host := os.Getenv("KUBERNETES_SERVICE_HOST")
+	port := os.Getenv("KUBERNETES_SERVICE_PORT")
+	if host == "" || port == "" {
+		return "", errors.ErrInvalidf("kubernetes: issuer_url is not configured and in-cluster environment variables (KUBERNETES_SERVICE_HOST, KUBERNETES_SERVICE_PORT) are not set")
+	}
+
+	return fmt.Sprintf("https://%s:%s", host, port), nil
+}
+
+// httpClient builds an *http.Client which trusts the CA certificate found at
+// the provided path. When the path is the in-cluster default and the file is
+// not present (i.e. not running in-cluster), the default client is returned.
+func (s *Server) httpClient(caPath string, isDefault bool) (*http.Client, error) {
+	caCert, err := os.ReadFile(caPath)
+	if err != nil {
+		if isDefault {
+			// not running in-cluster (or the default mount is absent);
+			// fall back to the system trust store.
+			return http.DefaultClient, nil
+		}
+
+		return nil, fmt.Errorf("kubernetes: reading CA certificate %q: %w", caPath, err)
+	}
+
+	pool, err := x509.SystemCertPool()
+	if err != nil || pool == nil {
+		pool = x509.NewCertPool()
+	}
+	if !pool.AppendCertsFromPEM(caCert) {
+		return nil, fmt.Errorf("kubernetes: parsing CA certificate %q", caPath)
+	}
+
+	return &http.Client{
+		Transport: &http.Transport{
+			TLSClientConfig: &tls.Config{
+				RootCAs: pool,
+			},
+		},
+	}, nil
+}
+
+// expiresAt determines the expiry for the created authentication. It prefers
+// the expiry embedded in the service account token, falling back to the
+// configured session token lifetime.
+func expiresAt(idToken *oidc.IDToken, tokenLifetime time.Duration) time.Time {
+	if !idToken.Expiry.IsZero() {
+		return idToken.Expiry
+	}
+
+	if tokenLifetime <= 0 {
+		tokenLifetime = 24 * time.Hour
+	}
+
+	return time.Now().UTC().Add(tokenLifetime)
+}
+
+// claims is the subset of Kubernetes service account token claims we persist
+// as authentication metadata.
+type claims struct {
+	Subject   string `json:"sub"`
+	Username  string `json:"username"`
+	Namespace string `json:"namespace"`
+}
