+// Package unmodifiable provides a read-only wrapper around a storage.Store.
+// All mutating operations (Create*, Update*, Delete*, Order*) return a
+// consistent sentinel error while read operations are delegated unchanged
+// to the underlying store.
+package unmodifiable
+
+import (
+	"context"
+	"errors"
+
+	"go.flipt.io/flipt/internal/storage"
+	"go.flipt.io/flipt/rpc/flipt"
+)
+
+// ErrReadOnly is returned when a mutating operation is attempted
+// against a read-only store.
+var ErrReadOnly = errors.New("storage is read-only")
+
+// Store wraps a storage.Store and enforces read-only behavior.
+// All mutating operations return ErrReadOnly while read operations
+// are delegated to the wrapped store.
+type Store struct {
+	storage.Store
+}
+
+// NewStore wraps the provided storage.Store in a read-only Store.
+func NewStore(store storage.Store) *Store {
+	return &Store{Store: store}
+}
+
+var _ storage.Store = (*Store)(nil)
+
+// CreateNamespace is not supported in read-only mode.
+func (s *Store) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
+	return nil, ErrReadOnly
+}
+
+// UpdateNamespace is not supported in read-only mode.
+func (s *Store) UpdateNamespace(ctx context.Context, r *flipt.UpdateNamespaceRequest) (*flipt.Namespace, error) {
+	return nil, ErrReadOnly
+}
+
+// DeleteNamespace is not supported in read-only mode.
+func (s *Store) DeleteNamespace(ctx context.Context, r *flipt.DeleteNamespaceRequest) error {
+	return ErrReadOnly
+}
+
+// CreateFlag is not supported in read-only mode.
+func (s *Store) CreateFlag(ctx context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
+	return nil, ErrReadOnly
+}
+
+// UpdateFlag is not supported in read-only mode.
+func (s *Store) UpdateFlag(ctx context.Context, r *flipt.UpdateFlagRequest) (*flipt.Flag, error) {
+	return nil, ErrReadOnly
+}
+
+// DeleteFlag is not supported in read-only mode.
+func (s *Store) DeleteFlag(ctx context.Context, r *flipt.DeleteFlagRequest) error {
+	return ErrReadOnly
+}
+
+// CreateVariant is not supported in read-only mode.
+func (s *Store) CreateVariant(ctx context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) {
+	return nil, ErrReadOnly
+}
+
+// UpdateVariant is not supported in read-only mode.
+func (s *Store) UpdateVariant(ctx context.Context, r *flipt.UpdateVariantRequest) (*flipt.Variant, error) {
+	return nil, ErrReadOnly
+}
+
+// DeleteVariant is not supported in read-only mode.
+func (s *Store) DeleteVariant(ctx context.Context, r *flipt.DeleteVariantRequest) error {
+	return ErrReadOnly
+}
+
+// CreateSegment is not supported in read-only mode.
+func (s *Store) CreateSegment(ctx context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment, error) {
+	return nil, ErrReadOnly
+}
+
+// UpdateSegment is not supported in read-only mode.
+func (s *Store) UpdateSegment(ctx context.Context, r *flipt.UpdateSegmentRequest) (*flipt.Segment, error) {
+	return nil, ErrReadOnly
+}
+
+// DeleteSegment is not supported in read-only mode.
+func (s *Store) DeleteSegment(ctx context.Context, r *flipt.DeleteSegmentRequest) error {
+	return ErrReadOnly
+}
+
