--- /dev/null
+++ b/internal/ext/common.go
@@ -0,0 +1,54 @@
+package ext
+
+// Document is the top level structure for import/export of flags and segments.
+type Document struct {
+	Flags    []*Flag    `yaml:"flags,omitempty"`
+	Segments []*Segment `yaml:"segments,omitempty"`
+}
+
+// Flag is a feature flag with its variants and rules.
+type Flag struct {
+	Key         string     `yaml:"key,omitempty"`
+	Name        string     `yaml:"name,omitempty"`
+	Description string     `yaml:"description,omitempty"`
+	Enabled     bool       `yaml:"enabled"`
+	Variants    []*Variant `yaml:"variants,omitempty"`
+	Rules       []*Rule    `yaml:"rules,omitempty"`
+}
+
+// Variant is a variant of a flag, optionally carrying an attachment.
+type Variant struct {
+	Key         string      `yaml:"key,omitempty"`
+	Name        string      `yaml:"name,omitempty"`
+	Description string      `yaml:"description,omitempty"`
+	Attachment  interface{} `yaml:"attachment,omitempty"`
+}
+
+// Rule is a targeting rule for a flag with its distributions.
+type Rule struct {
+	SegmentKey    string          `yaml:"segment,omitempty"`
+	Rank          uint            `yaml:"rank,omitempty"`
+	Distributions []*Distribution `yaml:"distributions,omitempty"`
+}
+
+// Distribution is the assignment of a variant within a rule.
+type Distribution struct {
+	VariantKey string  `yaml:"variant,omitempty"`
+	Rollout    float32 `yaml:"rollout,omitempty"`
+}
+
+// Segment is a segment of users defined by a set of constraints.
+type Segment struct {
+	Key         string        `yaml:"key,omitempty"`
+	Name        string        `yaml:"name,omitempty"`
+	Description string        `yaml:"description,omitempty"`
+	Constraints []*Constraint `yaml:"constraints,omitempty"`
+}
+
+// Constraint is a single condition within a segment.
+type Constraint struct {
+	Type     string `yaml:"type,omitempty"`
+	Property string `yaml:"property,omitempty"`
+	Operator string `yaml:"operator,omitempty"`
+	Value    string `yaml:"value,omitempty"`
+}
diff --git a/internal/ext/exporter.go b/internal/ext/exporter.go
new file mode 100644
index 0000000..e58aa6e
--- /dev/null
+++ b/internal/ext/exporter.go
@@ -0,0 +1,141 @@
+package ext
+
+import (
+	"context"
+	"encoding/json"
+	"io"
+
+	"gopkg.in/yaml.v2"
+
+	flipt "github.com/markphelps/flipt/rpc/flipt"
+	"github.com/markphelps/flipt/storage"
+)
+
+// lister is the interface used by the Exporter to read flags, rules and segments.
+type lister interface {
+	ListFlags(ctx context.Context, opts ...storage.QueryOption) ([]*flipt.Flag, error)
+	ListRules(ctx context.Context, flagKey string, opts ...storage.QueryOption) ([]*flipt.Rule, error)
+	ListSegments(ctx context.Context, opts ...storage.QueryOption) ([]*flipt.Segment, error)
+}
+
+// Exporter exports flags, variants, rules, distributions and segments from the
+// store into a YAML formatted document.
+type Exporter struct {
+	store     lister
+	batchSize uint64
+}
+
+// NewExporter returns a new Exporter backed by the provided store.
+func NewExporter(store lister) *Exporter {
+	return &Exporter{
+		store:     store,
+		batchSize: 25,
+	}
+}
+
+// Export writes all flags, variants, rules, distributions and segments in the
+// store to w as a YAML document. Variant attachments are decoded from their
+// JSON representation into native YAML structures.
+func (e *Exporter) Export(ctx context.Context, w io.Writer) error {
+	document := &Document{}
+
+	// export flags/variants in batches
+	var remaining = true
+	for batch := uint64(0); remaining; batch++ {
+		flags, err := e.store.ListFlags(ctx, storage.WithOffset(batch*e.batchSize), storage.WithLimit(e.batchSize))
+		if err != nil {
+			return err
+		}
+
+		remaining = uint64(len(flags)) == e.batchSize
+
+		for _, flag := range flags {
+			extFlag := &Flag{
+				Key:         flag.Key,
+				Name:        flag.Name,
+				Description: flag.Description,
+				Enabled:     flag.Enabled,
+			}
+
+			// map variant id => variant key so distributions can reference variants
+			variantKeyByID := make(map[string]string, len(flag.Variants))
+
+			for _, variant := range flag.Variants {
+				attachment := interface{}(nil)
+				if variant.Attachment != "" {
+					if err := json.Unmarshal([]byte(variant.Attachment), &attachment); err != nil {
+						return err
+					}
+				}
+
+				extFlag.Variants = append(extFlag.Variants, &Variant{
+					Key:         variant.Key,
+					Name:        variant.Name,
+					Description: variant.Description,
+					Attachment:  attachment,
+				})
+
+				variantKeyByID[variant.Id] = variant.Key
+			}
+
+			// export rules for flag
+			rules, err := e.store.ListRules(ctx, flag.Key)
+			if err != nil {
+				return err
+			}
+
+			for _, rule := range rules {
+				extRule := &Rule{
+					SegmentKey: rule.SegmentKey,
+					Rank:       uint(rule.Rank),
+				}
+
+				for _, distribution := range rule.Distributions {
+					extRule.Distributions = append(extRule.Distributions, &Distribution{
+						VariantKey: variantKeyByID[distribution.VariantId],
+						Rollout:    distribution.Rollout,
+					})
+				}
+
+				extFlag.Rules = append(extFlag.Rules, extRule)
+			}
+
+			document.Flags = append(document.Flags, extFlag)
+		}
+	}
+
+	// export segments/constraints in batches
+	remaining = true
+	for batch := uint64(0); remaining; batch++ {
+		segments, err := e.store.ListSegments(ctx, storage.WithOffset(batch*e.batchSize), storage.WithLimit(e.batchSize))
+		if err != nil {
+			return err
+		}
+
+		remaining = uint64(len(segments)) == e.batchSize
+
+		for _, segment := range segments {
+			extSegment := &Segment{
+				Key:         segment.Key,
+				Name:        segment.Name,
+				Description: segment.Description,
+			}
+
+			for _, constraint := range segment.Constraints {
+				extSegment.Constraints = append(extSegment.Constraints, &Constraint{
+					Type:     constraint.Type.String(),
+					Property: constraint.Property,
+					Operator: constraint.Operator,
+					Value:    constraint.Value,
+				})
+			}
+
+			document.Segments = append(document.Segments, extSegment)
+		}
+	}
+
+	encoder := yaml.NewEncoder(w)
+	defer encoder.Close()
+
+	return encoder.Encode(document)
+}
diff --git a/internal/ext/importer.go b/internal/ext/importer.go
new file mode 100644
index 0000000..0253f93
--- /dev/null
+++ b/internal/ext/importer.go
@@ -0,0 +1,169 @@
+package ext
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+
+	"gopkg.in/yaml.v2"
+
+	flipt "github.com/markphelps/flipt/rpc/flipt"
+)
+
+// creator is the interface used by the Importer to create flags, variants,
+// rules, distributions, segments and constraints.
+type creator interface {
+	CreateFlag(ctx context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error)
+	CreateVariant(ctx context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error)
+	CreateRule(ctx context.Context, r *flipt.CreateRuleRequest) (*flipt.Rule, error)
+	CreateDistribution(ctx context.Context, r *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
+	CreateSegment(ctx context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment, error)
+	CreateConstraint(ctx context.Context, r *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
+}
+
+// Importer imports flags, variants, rules, distributions and segments from a
+// YAML document into the store.
+type Importer struct {
+	store creator
+}
+
+// NewImporter returns a new Importer backed by the provided store.
+func NewImporter(store creator) *Importer {
+	return &Importer{
+		store: store,
+	}
+}
+
+// Import reads a YAML document from r and creates the corresponding flags,
+// variants, rules, distributions, segments and constraints in the store.
+// Variant attachments are encoded into JSON strings for storage.
+func (i *Importer) Import(ctx context.Context, r io.Reader) error {
+	var document Document
+	if err := yaml.NewDecoder(r).Decode(&document); err != nil {
+		return err
+	}
+
+	var (
+		// map flagKey:variantKey => *variant
+		createdVariants = make(map[string]*flipt.Variant)
+	)
+
+	// create flags/variants
+	for _, flag := range document.Flags {
+		createdFlag, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{
+			Key:         flag.Key,
+			Name:        flag.Name,
+			Description: flag.Description,
+			Enabled:     flag.Enabled,
+		})
+		if err != nil {
+			return err
+		}
+
+		for _, variant := range flag.Variants {
+			attachment := ""
+			if variant.Attachment != nil {
+				encoded, err := json.Marshal(convert(variant.Attachment))
+				if err != nil {
+					return err
+				}
+				attachment = string(encoded)
+			}
+
+			createdVariant, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{
+				FlagKey:     flag.Key,
+				Key:         variant.Key,
+				Name:        variant.Name,
+				Description: variant.Description,
+				Attachment:  attachment,
+			})
+			if err != nil {
+				return err
+			}
+
+			createdVariants[fmt.Sprintf("%s:%s", createdFlag.Key, createdVariant.Key)] = createdVariant
+		}
+	}
+
+	// create segments/constraints
+	for _, segment := range document.Segments {
+		if _, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
+			Key:         segment.Key,
+			Name:        segment.Name,
+			Description: segment.Description,
+		}); err != nil {
+			return err
+		}
+
+		for _, constraint := range segment.Constraints {
+			if _, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
+				SegmentKey: segment.Key,
+				Type:       flipt.ComparisonType(flipt.ComparisonType_value[constraint.Type]),
+				Property:   constraint.Property,
+				Operator:   constraint.Operator,
+				Value:      constraint.Value,
+			}); err != nil {
+				return err
+			}
+		}
+	}
+
+	// create rules/distributions
+	for _, flag := range document.Flags {
+		for _, rule := range flag.Rules {
+			createdRule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{
+				FlagKey:    flag.Key,
+				SegmentKey: rule.SegmentKey,
+				Rank:       int32(rule.Rank),
+			})
+			if err != nil {
+				return err
+			}
+
+			for _, distribution := range rule.Distributions {
+				variant, found := createdVariants[fmt.Sprintf("%s:%s", flag.Key, distribution.VariantKey)]
+				if !found {
+					return fmt.Errorf("finding variant: %s; flag: %s", distribution.VariantKey, flag.Key)
+				}
+
+				if _, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
+					FlagKey:   flag.Key,
+					RuleId:    createdRule.Id,
+					VariantId: variant.Id,
+					Rollout:   distribution.Rollout,
+				}); err != nil {
+					return err
+				}
+			}
+		}
+	}
+
+	return nil
+}
+
+// convert normalizes all map keys to string types (recursively) so that the
+// value can be serialized to JSON.
+func convert(v interface{}) interface{} {
+	switch v := v.(type) {
+	case map[interface{}]interface{}:
+		m := make(map[string]interface{}, len(v))
+		for key, value := range v {
+			m[fmt.Sprint(key)] = convert(value)
+		}
+		return m
+	case map[string]interface{}:
+		m := make(map[string]interface{}, len(v))
+		for key, value := range v {
+			m[key] = convert(value)
+		}
+		return m
+	case []interface{}:
+		for i, item := range v {
+			v[i] = convert(item)
+		}
+		return v
+	default:
+		return v
+	}
+}

