+
+// severityToCvssScore returns the CVSS score derived from the severity
+// by using the max value of the CVSS score range of the severity.
+func severityToCvssScore(severity string) float64 {
+	r := Cvss{Severity: severity}.SeverityToCvssScoreRange()
+	if r == "" {
+		return 0
+	}
+	parts := strings.Split(r, "-")
+	if len(parts) != 2 {
+		return 0
+	}
+	score, err := strconv.ParseFloat(parts[1], 64)
+	if err != nil {
+		return 0
+	}
+	return score
