 }
+
+// detectScanDest returns the list of the "ip:port" strings to be probed for
+// reachability. The scan destinations are derived exclusively from the
+// listening endpoints of the affected processes. An endpoint whose address is
+// "*" is expanded to all of the server's IPv4 addresses. The returned slice
+// is deduplicated and in a deterministic order.
+func (l *base) detectScanDest() []string {
+	seen := map[string]struct{}{}
+	scanDests := []string{}
+	add := func(dest string) {
+		if _, ok := seen[dest]; ok {
+			return
+		}
+		seen[dest] = struct{}{}
+		scanDests = append(scanDests, dest)
+	}
+
+	packNames := make([]string, 0, len(l.Packages))
+	for name := range l.Packages {
+		packNames = append(packNames, name)
+	}
+	sort.Strings(packNames)
+
+	for _, name := range packNames {
+		pack := l.Packages[name]
+		for _, proc := range pack.AffectedProcs {
+			for _, listenPort := range proc.ListenPorts {
+				if listenPort.Address == "*" {
+					for _, ip := range l.ServerInfo.IPv4Addrs {
+						add(ip + ":" + listenPort.Port)
+					}
+					continue
+				}
+				add(listenPort.Address + ":" + listenPort.Port)
+			}
+		}
+	}
+	return scanDests
+}
+
+// parseListenPorts parses an "ip:port" string such as "127.0.0.1:22", "*:80"
+// or "[::1]:443" into a ListenPort. The IPv6 brackets are preserved and the
+// address and the port are separated at the last colon.
+func (l *base) parseListenPorts(s string) models.ListenPort {
+	listenPort := models.ListenPort{
+		PortScanSuccessOn: []string{},
+	}
+	idx := strings.LastIndex(s, ":")
+	if idx < 0 {
+		listenPort.Port = s
+		return listenPort
+	}
+	listenPort.Address = s[:idx]
+	listenPort.Port = s[idx+1:]
+	return listenPort
+}
+
+// findPortScanSuccessOn returns the list of the IPv4 addresses on which the
+// given listen port was confirmed reachable (i.e. present in listenIPPorts).
+// An endpoint with a concrete address matches only that exact "ip:port", an
+// endpoint whose address is "*" matches any of the server's IPv4 addresses
+// with the same port. The returned slice is always non-nil, deduplicated and
+// in the order of ServerInfo.IPv4Addrs.
+func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.ListenPort) []string {
+	ipv4Addrs := map[string]struct{}{}
+	for _, ip := range l.ServerInfo.IPv4Addrs {
+		ipv4Addrs[ip] = struct{}{}
+	}
+
+	successOn := map[string]struct{}{}
+	for _, ipPort := range listenIPPorts {
+		listenPort := l.parseListenPorts(ipPort)
+		if listenPort.Port != searchListenPort.Port {
+			continue
+		}
+		if searchListenPort.Address == "*" {
+			if _, ok := ipv4Addrs[listenPort.Address]; ok {
+				successOn[listenPort.Address] = struct{}{}
+			}
+			continue
+		}
+		if listenPort.Address == searchListenPort.Address {
+			successOn[listenPort.Address] = struct{}{}
+		}
+	}
+
+	result := []string{}
+	if searchListenPort.Address == "*" {
+		for _, ip := range l.ServerInfo.IPv4Addrs {
+			if _, ok := successOn[ip]; ok {
+				result = append(result, ip)
+			}
+		}
+	} else if _, ok := successOn[searchListenPort.Address]; ok {
+		result = append(result, searchListenPort.Address)
+	}
+	return result
+}
+
+// updatePortStatus updates the PortScanSuccessOn field of the listen ports of
+// the affected processes in place with the successfully scanned "ip:port" list.
+func (l *base) updatePortStatus(listenIPPorts []string) {
+	for name, pack := range l.Packages {
+		for i, proc := range pack.AffectedProcs {
+			for j, listenPort := range proc.ListenPorts {
+				pack.AffectedProcs[i].ListenPorts[j].PortScanSuccessOn = l.findPortScanSuccessOn(listenIPPorts, listenPort)
+			}
+		}
+		l.Packages[name] = pack
+	}
+}
+
+// portScan attempts a TCP connection to each "ip:port" destination with a
+// short timeout and returns the destinations that were reachable.
+func (l *base) portScan(scanDests []string) []string {
+	listenIPPorts := []string{}
+	for _, dest := range scanDests {
+		conn, err := net.DialTimeout("tcp", dest, 1*time.Second)
+		if err != nil {
+			continue
+		}
+		listenIPPorts = append(listenIPPorts, dest)
+		conn.Close()
+	}
+	return listenIPPorts
+}
