+// RenameKernelSourcePackageName normalizes the kernel source package name
+// according to the distribution family.
+// For Debian and Raspbian, it replaces "linux-signed" and "linux-latest"
+// with "linux" and removes the "-amd64", "-arm64" and "-i386" suffixes.
+// For Ubuntu, it replaces "linux-signed" and "linux-meta" with "linux".
+// If the family is unrecognized, it returns the original name unchanged.
+func RenameKernelSourcePackageName(family, name string) string {
+	switch family {
+	case constant.Debian, constant.Raspbian:
+		name = strings.Replace(name, "linux-signed", "linux", 1)
+		name = strings.Replace(name, "linux-latest", "linux", 1)
+		name = strings.TrimSuffix(name, "-amd64")
+		name = strings.TrimSuffix(name, "-arm64")
+		name = strings.TrimSuffix(name, "-i386")
+		return name
+	case constant.Ubuntu:
+		name = strings.Replace(name, "linux-signed", "linux", 1)
+		name = strings.Replace(name, "linux-meta", "linux", 1)
+		return name
+	default:
+		return name
+	}
+}
+
+// IsKernelSourcePackage checks whether the package name is a kernel source
+// package based on its name pattern and the distribution family.
+// It covers patterns such as "linux", "linux-<version>" (e.g. "linux-5.10")
+// and various kernel variants (e.g. "linux-aws", "linux-azure",
+// "linux-hwe-5.15", "linux-azure-edge") for Debian, Ubuntu and Raspbian.
+// It returns true for valid kernel source packages and false otherwise.
+func IsKernelSourcePackage(family, name string) bool {
+	switch family {
+	case constant.Debian, constant.Ubuntu, constant.Raspbian:
+		// remove architecture suffix e.g. linux-libc-dev:amd64 -> linux-libc-dev
+		if i := strings.IndexRune(name, ':'); i >= 0 {
+			name = name[:i]
+		}
+		if name == "linux" {
+			return true
+		}
+		if !strings.HasPrefix(name, "linux-") {
+			return false
+		}
+		rest := name[len("linux-"):]
+		first := strings.Split(rest, "-")[0]
+		// version e.g. 5.10, 5.15.0
+		if isKernelVersion(first) {
+			return true
+		}
+		// known kernel variants
+		switch first {
+		case "aws", "azure", "gcp", "hwe", "oem", "raspi", "lowlatency", "grsec", "lts", "ti", "intel":
+			return true
+		}
+		return false
+	default:
+		return false
+	}
+}
+
+// isKernelVersion checks whether the string is a kernel version such as
+// 5.10 or 5.15.0 (digits separated by dots).
+func isKernelVersion(s string) bool {
+	if s == "" {
+		return false
+	}
+	for _, c := range s {
+		if c != '.' && (c < '0' || c > '9') {
+			return false
+		}
+	}
+	return true
+}
