+// toPURLType returns the PURL type for the given ecosystem or lockfile type.
+func toPURLType(t string) string {
+	switch t {
+	case "pom", "gradle", "sbt", "jar":
+		return "maven"
+	case "pip", "pipenv", "poetry", "uv", "python-pkg":
+		return "pypi"
+	case "gomod", "gobinary":
+		return "golang"
+	case "npm", "yarn", "pnpm", "node-pkg", "javascript":
+		return "npm"
+	case "cocoapods":
+		return "cocoapods"
+	case "cargo", "rustbinary":
+		return "cargo"
+	case "composer", "composer-vendor":
+		return "composer"
+	case "nuget", "dotnet-core", "packages-props":
+		return "nuget"
+	case "bundler", "gemspec":
