+	case "hex":
+		return "hex"
+	case "swift":
+		return "swift"
+	case "actions":
+		return "github"
+	default:
+		return t
+	}
+}
+
+// parsePkgName parses a package name into its PURL namespace, name and
+// subpath according to the package type (ecosystem). Fields that do not
+// apply for the given package type are returned as empty strings.
+func parsePkgName(t, n string) (namespace, name, subpath string) {
+	switch t {
+	case "maven":
+		if i := strings.Index(n, ":"); i >= 0 {
+			namespace, name = n[:i], n[i+1:]
+		} else {
+			name = n
+		}
+	case "pypi":
+		name = strings.ToLower(strings.ReplaceAll(n, "_", "-"))
+	case "golang":
+		if i := strings.LastIndex(n, "/"); i >= 0 {
+			namespace, name = n[:i], n[i+1:]
+		} else {
+			name = n
+		}
+	case "npm":
+		if strings.HasPrefix(n, "@") {
+			if i := strings.Index(n, "/"); i >= 0 {
+				namespace, name = n[:i], n[i+1:]
+			} else {
+				name = n
+			}
+		} else {
+			name = n
+		}
+	case "cocoapods":
+		if i := strings.Index(n, "/"); i >= 0 {
+			name, subpath = n[:i], n[i+1:]
+		} else {
+			name = n
+		}
+	default:
+		name = n
+	}
+	return namespace, name, subpath
+}
