new file mode 100644
index 000000000..f211bac3a
--- /dev/null
+++ b/lib/ai/model/tokencount.go
@@ -0,0 +1,163 @@
+/*
+ * Copyright 2023 Gravitational, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+
+package model
+
+import (
+	"sync"
+
+	"github.com/gravitational/trace"
+	"github.com/sashabaranov/go-openai"
+	"github.com/tiktoken-go/tokenizer/codec"
+)
+
+// Ref: https://github.com/openai/openai-cookbook/blob/594fc6c952425810e9ea5bd1a275c8ca5f32e8f9/examples/How_to_count_tokens_with_tiktoken.ipynb
+const (
+	// perMessage is the token "overhead" for each message
+	perMessage = 3
+
+	// perRequest is the number of tokens used up for each completion request
+	perRequest = 3
+
+	// perRole is the number of tokens used to encode a message's role
+	perRole = 1
+)
+
+// TokenCount is a struct that contains the number of tokens used in a single
+// invocation of the agent.
+type TokenCount struct {
+	prompt     TokenCounters
+	completion TokenCounters
+}
+
+// NewTokenCount creates a new TokenCount.
+func NewTokenCount() *TokenCount {
+	return &TokenCount{
+		prompt:     make(TokenCounters, 0),
+		completion: make(TokenCounters, 0),
+	}
+}
+
+// AddPromptCounter adds a prompt counter to the TokenCount.
+func (t *TokenCount) AddPromptCounter(prompt TokenCounter) {
+	if prompt == nil {
+		return
+	}
+	t.prompt = append(t.prompt, prompt)
+}
+
+// AddCompletionCounter adds a completion counter to the TokenCount.
+func (t *TokenCount) AddCompletionCounter(completion TokenCounter) {
+	if completion == nil {
+		return
+	}
+	t.completion = append(t.completion, completion)
+}
+
+// CountAll returns the total number of prompt and completion tokens used.
+func (t *TokenCount) CountAll() (int, int) {
+	return t.prompt.CountAll(), t.completion.CountAll()
+}
+
+// TokenCounter is an interface that defines a counter for tokens.
+type TokenCounter interface {
+	TokenCount() int
+}
+
+// TokenCounters is a slice of TokenCounter.
+type TokenCounters []TokenCounter
+
+// CountAll returns the total number of tokens in the TokenCounters.
+func (t TokenCounters) CountAll() int {
+	count := 0
+	for _, c := range t {
+		count += c.TokenCount()
+	}
+	return count
+}
+
+// StaticTokenCounter is a TokenCounter that returns a static token count.
+type StaticTokenCounter struct {
+	count int
+}
+
+// TokenCount returns the static token count.
+func (s *StaticTokenCounter) TokenCount() int {
+	return s.count
+}
+
+// NewPromptTokenCounter creates a new TokenCounter that counts the number of
+// tokens in the prompt.
+func NewPromptTokenCounter(prompt []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
+	count := 0
+	encoder := codec.NewCl100kBase()
+	for _, message := range prompt {
+		tokens, _, err := encoder.Encode(message.Content)
+		if err != nil {
+			return nil, trace.Wrap(err)
+		}
+		count += perMessage + perRole + len(tokens)
+	}
+	return &StaticTokenCounter{count: count}, nil
+}
+
+// NewSynchronousTokenCounter creates a new TokenCounter that counts the number
+// of tokens in a synchronous response.
+func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
+	encoder := codec.NewCl100kBase()
+	tokens, _, err := encoder.Encode(completion)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return &StaticTokenCounter{count: perRequest + len(tokens)}, nil
+}
+
+// AsynchronousTokenCounter is a TokenCounter that counts the number of tokens
+// in an asynchronous response.
+type AsynchronousTokenCounter struct {
+	mu       sync.Mutex
+	count    int
+	finished bool
+}
+
+// Add increments the token count by one.
+func (a *AsynchronousTokenCounter) Add() error {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+	if a.finished {
+		return trace.Errorf("token counter is finished")
+	}
+	a.count++
+	return nil
+}
+
+// TokenCount returns the total number of tokens in the asynchronous response.
+func (a *AsynchronousTokenCounter) TokenCount() int {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+	a.finished = true
+	return perRequest + a.count
+}
+
+// NewAsynchronousTokenCounter creates a new AsynchronousTokenCounter.
+func NewAsynchronousTokenCounter(start string) (*AsynchronousTokenCounter, error) {
+	encoder := codec.NewCl100kBase()
+	tokens, _, err := encoder.Encode(start)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return &AsynchronousTokenCounter{count: len(tokens)}, nil
+}
