+// migrateFieldsMap walks existing events and converts the legacy JSON-encoded
+// `Fields` string attribute into the native DynamoDB map attribute `FieldsMap`.
+// Storing the fields as a map makes individual fields addressable by DynamoDB
+// query expressions, enabling efficient field-level filtering.
+//
+// This function is not atomic on error but safely interruptible.
+// This means that the function may return an error without having processed
+// all data but no residual temporary or broken data is left and
+// the process can be resumed at any time by running this function again.
+//
+// Invariants:
+// - This function must not be called concurrently with itself.
+// - The fieldsMapMigrationLock must be held by the node.
+func (l *Log) migrateFieldsMap(ctx context.Context) error {
+	// If the migration has already completed, do nothing.
+	completed, err := l.isFieldsMapMigrationComplete(ctx)
+	if err != nil {
+		return trace.Wrap(err)
+	}
+	if completed {
+		return nil
+	}
+
+	var startKey map[string]*dynamodb.AttributeValue
+	totalProcessed := atomic.NewInt64(0)
+
+	for {
+		c := &dynamodb.ScanInput{
+			ExclusiveStartKey: startKey,
+			// Consistent reads so we don't miss events written concurrently.
+			ConsistentRead: aws.Bool(true),
+			// Process a bounded number of events per scan iteration so the
+			// migration can make (and report) steady progress on large tables.
+			Limit:     aws.Int64(DynamoBatchSize * maxMigrationWorkers),
+			TableName: aws.String(l.Tablename),
+			// Only select events that still need migration.
+			FilterExpression: aws.String("attribute_not_exists(" + keyFieldsMap + ")"),
+		}
+
+		scanOut, err := l.svc.Scan(c)
+		if err != nil {
+			return trace.Wrap(convertError(err))
+		}
+
+		writeRequests := make([]*dynamodb.WriteRequest, 0, DynamoBatchSize*maxMigrationWorkers)
+
+		for _, item := range scanOut.Items {
+			fieldsMap, err := fieldsMapFromItem(item)
+			if err != nil {
+				return trace.WrapWithMessage(err, "failed to migrate event fields for %s", eventKeyString(item))
+			}
+
+			// Validate that the converted map preserves the semantic content
+			// of the original JSON representation.
+			if err := validateFieldsMapRoundTrip(fieldsMap); err != nil {
+				return trace.WrapWithMessage(err, "failed to validate migrated event fields for %s", eventKeyString(item))
+			}
+
+			fieldsMapAttribute, err := dynamodbattribute.Marshal(fieldsMap)
+			if err != nil {
+				return trace.WrapWithMessage(err, "failed to marshal event fields for %s", eventKeyString(item))
+			}
+
+			// Add the FieldsMap attribute to the item and write the whole item
+			// back (BatchWriteItem only supports put and delete requests).
+			item[keyFieldsMap] = fieldsMapAttribute
+
+			writeRequests = append(writeRequests, &dynamodb.WriteRequest{
+				PutRequest: &dynamodb.PutRequest{
+					Item: item,
+				},
+			})
+		}
+
+		if len(writeRequests) > 0 {
+			if err := l.uploadBatch(writeRequests); err != nil {
+				return trace.Wrap(err)
+			}
+		}
+
+		totalProcessed.Add(int64(len(scanOut.Items)))
+		l.Infof("Migrated %d events to the %s format", totalProcessed.Load(), keyFieldsMap)
+
+		select {
+		case <-ctx.Done():
+			return trace.Wrap(ctx.Err())
+		default:
+		}
+
+		// Resume the scan at the end of the previous one. If there is no
+		// last evaluated key we have processed the whole dataset.
+		startKey = scanOut.LastEvaluatedKey
+		if len(startKey) == 0 {
+			break
+		}
+	}
+
+	// Mark the migration as complete so we don't re-scan on future startups.
+	return l.setFieldsMapMigrationComplete(ctx)
