+// Diag runs the Touch ID diagnostics and returns the results, including the
+// individual check flags and the computed availability status.
+func Diag() (*DiagResult, error) {
+	res := &DiagResult{}
+
+	switch diag := native.(type) {
+	case diagTID:
+		res.HasCompileSupport = diag.HasCompileSupport()
+		res.HasSignature = diag.HasSignature()
+		res.HasEntitlements = diag.HasEntitlements()
+		res.PassedLAPolicyTest = diag.PassedLAPolicyTest()
+		res.PassedSecureEnclaveTest = diag.PassedSecureEnclaveTest()
