+			return nil, trace.Wrap(err)
+		}
+		if res.PassedLAPolicyTest, err = diag.PassedLAPolicyTest(); err != nil {
+			return nil, trace.Wrap(err)
+		}
+		if res.PassedSecureEnclaveTest, err = diag.PassedSecureEnclaveTest(); err != nil {
+			return nil, trace.Wrap(err)
+		}
+	}
