+// defaultTerminalWidth is the width used to generate the table when the
+// terminal size cannot be determined.
+const defaultTerminalWidth = 80
+
+// MakeTableWithTruncatedColumn creates a new instance of the table with the
+// given column names and rows. The column whose title matches
+// truncatedColumn expands to occupy the remaining terminal space and its
+// cells are truncated with an ellipsis ("...") when they exceed the allotted
+// width. The other columns retain a maximum width calculated in proportion
+// to the terminal size. If the terminal size cannot be determined, a default
+// width of 80 characters is used. If truncatedColumn does not match any
+// column title, the table is rendered as usual with all columns and data
+// preserved. A nil or empty columnOrder creates a headless table.
+func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
+	width, _, err := term.GetSize(int(os.Stdin.Fd()))
+	if err != nil {
+		width = defaultTerminalWidth
+	}
+
+	var t Table
+	if len(columnOrder) == 0 {
+		columnCount := 0
+		for _, row := range rows {
+			columnCount = max(columnCount, len(row))
+		}
+		t = MakeHeadlessTable(columnCount)
+		for _, row := range rows {
+			t.AddRow(row)
+		}
+		return t
+	}
+
+	t = MakeTable(columnOrder)
+
+	// If the truncated column does not match any column title, render the
+	// table as usual, preserving all columns and data.
+	found := false
+	for _, colName := range columnOrder {
+		if colName == truncatedColumn {
+			found = true
+			break
+		}
+	}
+	if !found {
+		for _, row := range rows {
+			t.AddRow(row)
+		}
+		return t
+	}
+
+	truncatedColMinSize := 16
+	maxColWidth := width
+	if len(columnOrder) > 1 {
+		maxColWidth = (width - truncatedColMinSize) / (len(columnOrder) - 1)
+	}
+
+	totalLen := 0
+	for collIndex, colName := range columnOrder {
+		if colName == truncatedColumn { // truncated column is handled separately in next loop
+			continue
+		}
+		column := &t.columns[collIndex]
+		column.MaxCellLength = len(colName)
+		for _, row := range rows {
+			if collIndex < len(row) && len(row[collIndex]) > column.MaxCellLength {
+				column.MaxCellLength = len(row[collIndex])
+			}
+		}
+		if column.MaxCellLength > maxColWidth {
+			column.MaxCellLength = maxColWidth
+			totalLen += column.MaxCellLength + 4 // "...<space>"
+		} else {
+			totalLen += column.MaxCellLength + 1 // +1 for column separator
+		}
+	}
+
+	for i := range t.columns {
+		if t.columns[i].Title == truncatedColumn {
+			t.columns[i].MaxCellLength = width - totalLen - len("... ")
+			if t.columns[i].MaxCellLength < 0 {
+				t.columns[i].MaxCellLength = 0
+			}
+		}
+	}
+
+	for _, row := range rows {
+		t.AddRow(row)
+	}
+	return t
+}
