+// AsyncEmitterConfig configures the async emitter
+type AsyncEmitterConfig struct {
+	// Inner is the emitter that receives the events
+	Inner Emitter
+	// BufferSize is the size of the buffer used to queue events,
+	// defaults to defaults.AsyncBufferSize
+	BufferSize int
+}
+
+// CheckAndSetDefaults checks and sets default values
+func (c *AsyncEmitterConfig) CheckAndSetDefaults() error {
+	if c.Inner == nil {
+		return trace.BadParameter("missing parameter Inner")
+	}
+	if c.BufferSize <= 0 {
+		c.BufferSize = defaults.AsyncBufferSize
+	}
+	return nil
+}
+
+// NewAsyncEmitter returns a new instance of the async emitter
+func NewAsyncEmitter(cfg AsyncEmitterConfig) (*AsyncEmitter, error) {
+	if err := cfg.CheckAndSetDefaults(); err != nil {
+		return nil, trace.Wrap(err)
+	}
+	ctx, cancel := context.WithCancel(context.Background())
+	emitter := &AsyncEmitter{
+		cfg:    cfg,
+		ctx:    ctx,
+		cancel: cancel,
+		events: make(chan AuditEvent, cfg.BufferSize),
+	}
+	go emitter.processEvents()
+	return emitter, nil
+}
+
+// AsyncEmitter is an emitter that buffers events in memory
+// and emits them in the background, it never blocks the caller
+// and drops events when the buffer is full
+type AsyncEmitter struct {
+	cfg    AsyncEmitterConfig
+	ctx    context.Context
+	cancel context.CancelFunc
+	events chan AuditEvent
+}
+
+// processEvents emits events in the background
+func (a *AsyncEmitter) processEvents() {
+	for {
+		select {
+		case event := <-a.events:
+			if err := a.cfg.Inner.EmitAuditEvent(a.ctx, event); err != nil {
+				log.WithError(err).Errorf("Failed to emit audit event.")
+			}
+		case <-a.ctx.Done():
+			return
+		}
+	}
+}
+
+// EmitAuditEvent emits audit event, it never blocks,
+// if the buffer is full, the event is dropped
+func (a *AsyncEmitter) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
+	select {
+	case <-a.ctx.Done():
+		return trace.ConnectionProblem(a.ctx.Err(), "emitter has been closed")
+	default:
+	}
+	select {
+	case a.events <- event:
+		return nil
+	case <-a.ctx.Done():
+		return trace.ConnectionProblem(a.ctx.Err(), "emitter has been closed")
+	default:
+		// the buffer is full, drop the event
+		log.Debugf("Async emitter buffer is full, dropping event: %v", event)
+		return nil
+	}
+}
+
+// Close closes the emitter, it cancels the background processing
+// and stops accepting new events
+func (a *AsyncEmitter) Close() error {
+	a.cancel()
+	return nil
+}
+
 // DiscardStream returns a stream that discards all events
 type DiscardStream struct {
 }
