+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+package utils
+
+import (
+	"sync"
+
+	"github.com/gravitational/trace"
+)
+
+// CircularBuffer is a circular buffer with a fixed size
+type CircularBuffer struct {
+	// data is a slice of values
+	data []float64
+	// start is an index of the first element
+	start int
+	// end is an index of the last element
+	end int
+	// size is a number of elements in the buffer
+	size int
+	// lock is a lock to protect the buffer
+	lock sync.Mutex
+}
+
+// NewCircularBuffer returns a new circular buffer with a given size
+func NewCircularBuffer(size int) (*CircularBuffer, error) {
+	if size <= 0 {
+		return nil, trace.BadParameter("size must be positive, got %v", size)
+	}
+	return &CircularBuffer{
+		data:  make([]float64, size),
+		start: -1,
+		end:   -1,
+		size:  0,
+	}, nil
+}
+
+// Add adds a new value to the buffer
+func (c *CircularBuffer) Add(d float64) {
+	c.lock.Lock()
+	defer c.lock.Unlock()
+	// if the buffer is empty, add the first element
+	if c.size == 0 {
+		c.data[0] = d
+		c.start = 0
+		c.end = 0
+		c.size = 1
+		return
+	}
+	// if the buffer is not full, add the new element
+	if c.size < len(c.data) {
+		c.end = (c.end + 1) % len(c.data)
+		c.data[c.end] = d
+		c.size++
+		return
+	}
+	// if the buffer is full, overwrite the oldest element
+	c.end = c.start
+	c.data[c.end] = d
+	c.start = (c.start + 1) % len(c.data)
+}
+
+// Data returns up to n most recent values in the buffer
+func (c *CircularBuffer) Data(n int) []float64 {
+	if n <= 0 || c.size == 0 {
+		return nil
+	}
+	c.lock.Lock()
+	defer c.lock.Unlock()
+	if n > c.size {
+		n = c.size
+	}
+	out := make([]float64, 0, n)
+	for i := 0; i < n; i++ {
+		// start from the oldest of the most recent n elements
+		idx := (c.end - n + 1 + i + len(c.data)) % len(c.data)
+		out = append(out, c.data[idx])
+	}
+	return out
+}
