+// getWatcherEvents returns a map of watcher events by resource
+func getWatcherEvents(metrics map[string]*dto.MetricFamily) map[string]Event {
+	events := make(map[string]Event)
+	for _, counter := range metricCounters(metrics[teleport.MetricWatcherEvents]) {
+		resource := ""
+		for _, label := range counter.Label {
+			if label.GetName() == teleport.TagResource {
+				resource = label.GetValue()
+			}
+		}
+		events[resource] = Event{
+			Resource: resource,
+			Counter:  Counter{Count: int64(counter.Counter.GetValue())},
+		}
+	}
+	// add event sizes from the event size histogram
+	for _, hist := range metricHistograms(metrics[teleport.MetricWatcherEventsSizeHistogram]) {
+		resource := ""
+		for _, label := range hist.Label {
+			if label.GetName() == teleport.TagResource {
+				resource = label.GetValue()
+			}
+		}
+		event, ok := events[resource]
+		if !ok {
+			event = Event{Resource: resource}
+		}
+		event.Size = hist.Histogram.GetSampleSum()
+		events[resource] = event
+	}
+	return events
