@@ -0,0 +1,133 @@
+package cache
+
+import (
+	"errors"
+	"sync"
+	"time"
+)
+
+// ErrNotFound is returned when a key is not present in the cache or has expired
+var ErrNotFound = errors.New("cache: key not found")
+
+// SimpleCache is a generic interface for a simple key/value cache with TTL support.
+// Values are strongly typed, so no type assertions are needed when retrieving them.
+type SimpleCache[V any] interface {
+	// Add stores the given value under the given key. The value does not expire.
+	Add(key string, value V) error
+	// AddWithTTL stores the given value under the given key, with an expiration
+	// time of ttl from now.
+	AddWithTTL(key string, value V, ttl time.Duration) error
+	// Get returns the value stored under the given key, if it exists and has not
+	// expired. It returns the zero value of V and a non-nil error otherwise.
+	Get(key string) (V, error)
+	// GetWithLoader returns the value stored under the given key, if it exists and
+	// has not expired. If the key is missing or expired, it invokes the loader to
+	// obtain the value, stores it with the TTL returned by the loader and returns
+	// it. If the loader returns an error, that error is propagated and no value
+	// is stored.
+	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)
+	// Keys returns a list of all active keys currently stored in the cache. Keys
+	// corresponding to expired entries are not included.
+	Keys() []string
+}
+
+type cacheItem[V any] struct {
+	value    V
+	ttl      time.Duration
+	expireAt time.Time
+}
+
+// expired returns true if the item has a TTL and its expiration time has passed
+func (i *cacheItem[V]) expired() bool {
+	return i.ttl > 0 && i.expireAt.Before(time.Now())
+}
+
+// touch extends the item's life, resetting its expiration time from now
+func (i *cacheItem[V]) touch() {
+	if i.ttl > 0 {
+		i.expireAt = time.Now().Add(i.ttl)
+	}
+}
+
+type simpleCache[V any] struct {
+	mu    sync.RWMutex
+	items map[string]cacheItem[V]
+}
+
+// NewSimpleCache returns a new SimpleCache[V]
+func NewSimpleCache[V any]() SimpleCache[V] {
+	return &simpleCache[V]{
+		items: make(map[string]cacheItem[V]),
+	}
+}
+
+func (c *simpleCache[V]) Add(key string, value V) error {
+	return c.AddWithTTL(key, value, 0)
+}
+
+func (c *simpleCache[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	c.items[key] = newCacheItem(value, ttl)
+	return nil
+}
+
+func (c *simpleCache[V]) Get(key string) (V, error) {
+	var zero V
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	item, ok := c.items[key]
+	if !ok || item.expired() {
+		delete(c.items, key)
+		return zero, ErrNotFound
+	}
+	// Every lookup touches the item, hence extending its life
+	item.touch()
+	return item.value, nil
+}
+
+func (c *simpleCache[V]) GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error) {
+	var zero V
+	c.mu.Lock()
+	if item, ok := c.items[key]; ok && !item.expired() {
+		item.touch()
+		c.mu.Unlock()
+		return item.value, nil
+	}
+	c.mu.Unlock()
+
+	// Cache miss: invoke the loader to obtain the value
+	value, ttl, err := loader(key)
+	if err != nil {
+		return zero, err
+	}
+
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	// Re-check in case the value was added by a concurrent call in the meantime
+	if item, ok := c.items[key]; ok && !item.expired() {
+		return item.value, nil
+	}
+	c.items[key] = newCacheItem(value, ttl)
+	return value, nil
+}
+
+func (c *simpleCache[V]) Keys() []string {
+	c.mu.RLock()
+	defer c.mu.RUnlock()
+	keys := make([]string, 0, len(c.items))
+	for key, item := range c.items {
+		if !item.expired() {
+			keys = append(keys, key)
+		}
+	}
+	return keys
+}
+
+func newCacheItem[V any](value V, ttl time.Duration) cacheItem[V] {
+	item := cacheItem[V]{value: value, ttl: ttl}
+	if ttl > 0 {
+		item.expireAt = time.Now().Add(ttl)
+	}
+	return item
+}

