+package criteria
+
+import (
+	"encoding/json"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// Criteria is a structure that encapsulates logical expressions
+type Criteria struct {
+	Expression squirrel.Sqlizer
+	Sort       string
+	Order      string
+	Max        int
+	Offset     int
+}
+
+// ToSql converts the internal expression to a SQL query
+func (c Criteria) ToSql() (string, []interface{}, error) {
+	return c.Expression.ToSql()
+}
+
+// MarshalJSON serializes the Criteria to a JSON string
+func (c Criteria) MarshalJSON() ([]byte, error) {
+	jc := jsonCriteria{
+		Sort:   c.Sort,
+		Order:  c.Order,
+		Max:    c.Max,
+		Offset: c.Offset,
+	}
+	switch expr := c.Expression.(type) {
+	case All:
+		jc.All = toInterfaceSlice(expr)
+	case Any:
+		jc.Any = toInterfaceSlice(expr)
+	case nil:
+		// no expression
+	default:
+		return c.marshalWithExpression()
+	}
+	return json.Marshal(jc)
+}
+
+// marshalWithExpression serializes the Criteria when the top level expression
+// is not an All/Any group, merging the expression JSON with the pagination fields
+func (c Criteria) marshalWithExpression() ([]byte, error) {
+	result := map[string]interface{}{}
+	if c.Expression != nil {
+		b, err := json.Marshal(c.Expression)
+		if err != nil {
+			return nil, err
+		}
+		var expr map[string]interface{}
+		if err := json.Unmarshal(b, &expr); err != nil {
+			return nil, err
+		}
+		for k, v := range expr {
+			result[k] = v
+		}
+	}
+	if c.Sort != "" {
+		result["sort"] = c.Sort
+	}
+	if c.Order != "" {
+		result["order"] = c.Order
+	}
+	if c.Max > 0 {
+		result["max"] = c.Max
+	}
+	if c.Offset > 0 {
+		result["offset"] = c.Offset
+	}
+	return json.Marshal(result)
+}
+
+// UnmarshalJSON deserializes the Criteria from a JSON string
+func (c *Criteria) UnmarshalJSON(data []byte) error {
+	var m map[string]interface{}
+	if err := json.Unmarshal(data, &m); err != nil {
+		return err
+	}
+	if v, ok := m["sort"].(string); ok {
+		c.Sort = v
+	}
+	if v, ok := m["order"].(string); ok {
+		c.Order = v
+	}
+	if v, ok := m["max"].(float64); ok {
+		c.Max = int(v)
+	}
+	if v, ok := m["offset"].(float64); ok {
+		c.Offset = int(v)
+	}
+	delete(m, "sort")
+	delete(m, "order")
+	delete(m, "max")
+	delete(m, "offset")
+	if len(m) > 0 {
+		expr, err := unmarshalExpression(m)
+		if err != nil {
+			return err
+		}
+		c.Expression = expr
+	}
+	return nil
+}
