@@ -0,0 +1,39 @@
+package criteria
+
+import (
+	"errors"
+	"time"
+)
+
+// Time is a wrapper for time.Time that serializes to a JSON string in the format 2006-01-02
+type Time time.Time
+
+// MarshalJSON serializes the Time to a JSON string in the format 2006-01-02
+func (t Time) MarshalJSON() ([]byte, error) {
+	return []byte(`"` + time.Time(t).Format("2006-01-02") + `"`), nil
+}
+
+// UnmarshalJSON deserializes the Time from a JSON string in the format 2006-01-02
+func (t *Time) UnmarshalJSON(data []byte) error {
+	str := string(data)
+	if len(str) < 2 {
+		return errors.New("invalid date")
+	}
+	str = str[1 : len(str)-1]
+	parsed, err := time.Parse("2006-01-02", str)
+	if err != nil {
+		return err
+	}
+	*t = Time(parsed)
+	return nil
+}
+
+// fieldMap maps interface field names to fully qualified SQL columns
+var fieldMap = map[string]string{
+	"title":   "media_file.title",
+	"artist":  "media_file.artist",
+	"album":   "media_file.album",
+	"loved":   "annotation.starred",
+	"year":    "media_file.year",
+	"comment": "media_file.comment",
+}
diff --git a/model/criteria/json.go b/model/criteria/json.go
new file mode 100644
index 00000000..a1bfa35d
--- /dev/null
+++ b/model/criteria/json.go
@@ -0,0 +1,171 @@
+package criteria
+
+import (
+	"fmt"
+	"time"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// jsonCriteria is the JSON representation of Criteria
+type jsonCriteria struct {
+	All    []interface{} `json:"all,omitempty"`
+	Any    []interface{} `json:"any,omitempty"`
+	Sort   string        `json:"sort,omitempty"`
+	Order  string        `json:"order,omitempty"`
+	Max    int           `json:"max,omitempty"`
+	Offset int           `json:"offset,omitempty"`
+}
+
+// toInterfaceSlice converts a slice of Sqlizer to a slice of interface{}
+func toInterfaceSlice(s []squirrel.Sqlizer) []interface{} {
+	result := make([]interface{}, len(s))
+	for i, v := range s {
+		result[i] = v
+	}
+	return result
+}
+
+// unmarshalExpression converts a JSON object to a Sqlizer expression
+func unmarshalExpression(m map[string]interface{}) (squirrel.Sqlizer, error) {
+	if len(m) != 1 {
+		return nil, fmt.Errorf("invalid expression: %v", m)
+	}
+	for key, value := range m {
+		switch key {
+		case "all":
+			items, ok := value.([]interface{})
+			if !ok {
+				return nil, fmt.Errorf("invalid all expression: %v", value)
+			}
+			all := make(All, len(items))
+			for i, item := range items {
+				expr, err := unmarshalItem(item)
+				if err != nil {
+					return nil, err
+				}
+				all[i] = expr
+			}
+			return all, nil
+		case "any":
+			items, ok := value.([]interface{})
+			if !ok {
+				return nil, fmt.Errorf("invalid any expression: %v", value)
+			}
+			anyExpr := make(Any, len(items))
+			for i, item := range items {
+				expr, err := unmarshalItem(item)
+				if err != nil {
+					return nil, err
+				}
+				anyExpr[i] = expr
+			}
+			return anyExpr, nil
+		default:
+			return unmarshalOperator(key, value)
+		}
+	}
+	return nil, fmt.Errorf("invalid expression: %v", m)
+}
+
+// unmarshalItem converts a JSON item to a Sqlizer expression
+func unmarshalItem(item interface{}) (squirrel.Sqlizer, error) {
+	m, ok := item.(map[string]interface{})
+	if !ok {
+		return nil, fmt.Errorf("invalid expression item: %v", item)
+	}
+	return unmarshalExpression(m)
+}
+
+// unmarshalOperator converts a JSON object to an operator
+func unmarshalOperator(field string, value interface{}) (squirrel.Sqlizer, error) {
+	opMap, ok := value.(map[string]interface{})
+	if !ok {
+		return nil, fmt.Errorf("invalid operator: %v", value)
+	}
+	if len(opMap) != 1 {
+		return nil, fmt.Errorf("invalid operator: %v", value)
+	}
+	for op, v := range opMap {
+		switch op {
+		case "is":
+			return Is{Field: field, Value: v}, nil
+		case "isNot":
+			return IsNot{Field: field, Value: v}, nil
+		case "gt":
+			return Gt{Field: field, Value: v}, nil
+		case "lt":
+			return Lt{Field: field, Value: v}, nil
+		case "before":
+			t, err := parseTime(v)
+			if err != nil {
+				return nil, err
+			}
+			return Before{Field: field, Value: t}, nil
+		case "after":
+			t, err := parseTime(v)
+			if err != nil {
+				return nil, err
+			}
+			return After{Field: field, Value: t}, nil
+		case "contains":
+			s, ok := v.(string)
+			if !ok {
+				return nil, fmt.Errorf("invalid contains value: %v", v)
+			}
+			return Contains{Field: field, Value: s}, nil
+		case "notContains":
+			s, ok := v.(string)
+			if !ok {
+				return nil, fmt.Errorf("invalid notContains value: %v", v)
+			}
+			return NotContains{Field: field, Value: s}, nil
+		case "startsWith":
+			s, ok := v.(string)
+			if !ok {
+				return nil, fmt.Errorf("invalid startsWith value: %v", v)
+			}
+			return StartsWith{Field: field, Value: s}, nil
+		case "endsWith":
+			s, ok := v.(string)
+			if !ok {
+				return nil, fmt.Errorf("invalid endsWith value: %v", v)
+			}
+			return EndsWith{Field: field, Value: s}, nil
+		case "inTheRange":
+			r, ok := v.([]interface{})
+			if !ok || len(r) != 2 {
+				return nil, fmt.Errorf("invalid inTheRange value: %v", v)
+			}
+			return InTheRange{Field: field, From: r[0], To: r[1]}, nil
+		case "inTheLast":
+			d, ok := v.(float64)
+			if !ok {
+				return nil, fmt.Errorf("invalid inTheLast value: %v", v)
+			}
+			return InTheLast{Field: field, Days: int(d)}, nil
+		case "notInTheLast":
+			d, ok := v.(float64)
+			if !ok {
+				return nil, fmt.Errorf("invalid notInTheLast value: %v", v)
+			}
+			return NotInTheLast{Field: field, Days: int(d)}, nil
+		default:
+			return nil, fmt.Errorf("unknown operator: %s", op)
+		}
+	}
+	return nil, fmt.Errorf("invalid operator: %v", value)
+}
+
+// parseTime parses a JSON string to a Time in the format 2006-01-02
+func parseTime(v interface{}) (Time, error) {
+	s, ok := v.(string)
+	if !ok {
+		return Time{}, fmt.Errorf("invalid date: %v", v)
+	}
+	t, err := time.Parse("2006-01-02", s)
+	if err != nil {
+		return Time{}, err
+	}
+	return Time(t), nil
+}
