+package criteria
+
+import (
+	"encoding/json"
+	"time"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// All is a logical AND operator
+type All []squirrel.Sqlizer
+
+// Any is a logical OR operator
+type Any []squirrel.Sqlizer
+
+// Is is an equality operator
+type Is struct {
+	Field string
+	Value interface{}
+}
+
+// IsNot is an inequality operator
+type IsNot struct {
+	Field string
+	Value interface{}
+}
+
+// Gt is a greater than operator
+type Gt struct {
+	Field string
+	Value interface{}
+}
+
+// Lt is a less than operator
+type Lt struct {
+	Field string
+	Value interface{}
+}
+
+// Before is a date before operator
+type Before struct {
+	Field string
+	Value interface{}
+}
+
+// After is a date after operator
+type After struct {
+	Field string
+	Value interface{}
+}
+
+// Contains is a text contains operator
+type Contains struct {
+	Field string
+	Value string
+}
+
+// NotContains is a text not contains operator
+type NotContains struct {
+	Field string
+	Value string
+}
+
+// StartsWith is a text starts with operator
+type StartsWith struct {
+	Field string
+	Value string
+}
+
+// EndsWith is a text ends with operator
+type EndsWith struct {
+	Field string
+	Value string
+}
+
+// InTheRange is a range operator
+type InTheRange struct {
+	Field string
+	From  interface{}
+	To    interface{}
+}
+
+// InTheLast is an operator for dates within the last N days
+type InTheLast struct {
+	Field string
+	Days  int
+}
+
+// NotInTheLast is an operator for dates not within the last N days
+type NotInTheLast struct {
+	Field string
+	Days  int
+}
+
+// ToSql generates a SQL statement for the All operator
+func (a All) ToSql() (string, []interface{}, error) {
+	return squirrel.And(a).ToSql()
+}
+
+// MarshalJSON serializes the All operator to JSON
+func (a All) MarshalJSON() ([]byte, error) {
+	items := make([]interface{}, len(a))
+	for i, item := range a {
+		items[i] = item
+	}
+	return json.Marshal(map[string]interface{}{
+		"all": items,
+	})
+}
+
+// ToSql generates a SQL statement for the Any operator
+func (a Any) ToSql() (string, []interface{}, error) {
+	return squirrel.Or(a).ToSql()
+}
+
+// MarshalJSON serializes the Any operator to JSON
+func (a Any) MarshalJSON() ([]byte, error) {
+	items := make([]interface{}, len(a))
+	for i, item := range a {
+		items[i] = item
+	}
+	return json.Marshal(map[string]interface{}{
+		"any": items,
+	})
