+func (e *externalMetadata) ArtistImage(ctx context.Context, id string) (io.ReadCloser, error) {
+	artist, err := e.getArtist(ctx, id)
+	if err != nil {
+		return nil, err
+	}
+	// If we don't have any image, retrieves it now
+	if artist.LargeImageUrl == "" {
+		log.Debug(ctx, "ArtistImage not cached. Retrieving it now", "updatedAt", artist.ExternalInfoUpdatedAt, "id", id, "name", artist.Name)
+		err = e.refreshArtistImage(ctx, artist)
+		if err != nil {
+			return nil, err
+		}
+	}
+	// If image is expired, trigger a refresh in the background
+	if time.Since(artist.ExternalInfoUpdatedAt) > consts.ArtistInfoTimeToLive {
+		log.Debug(ctx, "Found expired cached ArtistImage, refreshing in the background", "updatedAt", artist.ExternalInfoUpdatedAt, "name", artist.Name)
+		go func() {
+			ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
+			defer cancel()
+			err := e.refreshArtistImage(ctx, artist)
+			if err != nil {
+				log.Error(ctx, "Error refreshing ArtistImage", "id", id, "name", artist.Name, err)
+			}
+		}()
+	}
+
+	if artist.LargeImageUrl == "" {
+		return nil, errors.New("no image available")
+	}
+
+	req, err := http.NewRequestWithContext(ctx, http.MethodGet, artist.LargeImageUrl, nil)
+	if err != nil {
+		return nil, err
+	}
+	hc := http.Client{Timeout: 5 * time.Second}
+	resp, err := hc.Do(req)
+	if err != nil {
+		return nil, err
+	}
+	if resp.StatusCode != http.StatusOK {
+		resp.Body.Close()
+		return nil, fmt.Errorf("error retrieving image from %s: %s", artist.LargeImageUrl, resp.Status)
+	}
+	return resp.Body, nil
+}
+
+func (e *externalMetadata) refreshArtistImage(ctx context.Context, artist *auxArtist) error {
+	// Get MBID first, if it is not yet available
+	if artist.MbzArtistID == "" {
+		mbid, err := e.ag.GetMBID(ctx, artist.ID, artist.Name)
+		if mbid != "" && err == nil {
+			artist.MbzArtistID = mbid
+		}
+	}
+	e.callGetImage(ctx, e.ag, artist)
+	if utils.IsCtxDone(ctx) {
+		log.Warn(ctx, "ArtistImage update canceled", ctx.Err())
+		return ctx.Err()
+	}
+	artist.ExternalInfoUpdatedAt = time.Now()
+	err := e.ds.Artist(ctx).Put(&artist.Artist)
+	if err != nil {
+		log.Error(ctx, "Error trying to update artist external information", "id", artist.ID, "name", artist.Name, err)
+	}
+	return nil
+}
