+++ b/cmd/backup.go
@@ -0,0 +1,103 @@
+package cmd
+
+import (
+	"bufio"
+	"fmt"
+	"os"
+	"strings"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/db"
+	"github.com/navidrome/navidrome/log"
+	"github.com/spf13/cobra"
+)
+
+var (
+	pruneForce   bool
+	restoreForce bool
+	backupFile   string
+)
+
+var backupCmd = &cobra.Command{
+	Use:   "backup",
+	Short: "Backup and restore the Navidrome database",
+}
+
+var backupCreateCmd = &cobra.Command{
+	Use:   "create",
+	Short: "Create a backup of the Navidrome database",
+	Run: func(cmd *cobra.Command, args []string) {
+		backup, err := db.Db().Backup(cmd.Context())
+		if err != nil {
+			log.Error("Error creating backup", err)
+			os.Exit(1)
+		}
+		fmt.Println("Backup created:", backup)
+	},
+}
+
+var backupPruneCmd = &cobra.Command{
+	Use:   "prune",
+	Short: "Prune old backups, keeping only the latest backup.count files",
+	Run: func(cmd *cobra.Command, args []string) {
+		defer func() { pruneForce = false }()
+		if conf.Server.Backup.Count == 0 && !pruneForce {
+			if !confirm("backup.count is 0, so ALL backups will be deleted. Are you sure?") {
+				log.Warn("Backup prune cancelled")
+				return
+			}
+		}
+		pruned, err := db.Db().Prune(cmd.Context())
+		if err != nil {
+			log.Error("Error pruning backups", err)
+			os.Exit(1)
+		}
+		fmt.Println("Pruned", pruned, "backup(s)")
+	},
+}
+
+var backupRestoreCmd = &cobra.Command{
+	Use:   "restore",
+	Short: "Restore the Navidrome database from a backup",
+	Run: func(cmd *cobra.Command, args []string) {
+		defer func() {
+			restoreForce = false
+			backupFile = ""
+		}()
+		if backupFile == "" {
+			log.Error("Error: --backup-file is required")
+			os.Exit(1)
+		}
+		if !restoreForce {
+			if !confirm(fmt.Sprintf("This will replace the current database with the backup at '%s'. Are you sure?", backupFile)) {
+				log.Warn("Backup restore cancelled")
+				return
+			}
+		}
+		if err := db.Db().Restore(cmd.Context(), backupFile); err != nil {
+			log.Error("Error restoring backup", err)
+			os.Exit(1)
+		}
+		fmt.Println("Database restored from backup:", backupFile)
+	},
+}
+
+// confirm asks the user to confirm a destructive action, returning true only on "y"/"yes".
+func confirm(prompt string) bool {
+	reader := bufio.NewReader(os.Stdin)
+	fmt.Print(prompt + " (y/N) ")
+	response, _ := reader.ReadString('\n')
+	response = strings.ToLower(strings.TrimSpace(response))
+	return response == "y" || response == "yes"
+}
+
+func init() {
+	rootCmd.AddCommand(backupCmd)
+	backupCmd.AddCommand(backupCreateCmd)
+	backupCmd.AddCommand(backupPruneCmd)
+	backupCmd.AddCommand(backupRestoreCmd)
+
+	backupPruneCmd.Flags().BoolVarP(&pruneForce, "force", "f", false, "force prune without confirmation")
+	backupRestoreCmd.Flags().BoolVarP(&restoreForce, "force", "f", false, "force restore without confirmation")
+	backupRestoreCmd.Flags().StringVar(&backupFile, "backup-file", "", "path to the backup file to restore from")
+}
