diff --git a/db/backup.go b/db/backup.go
new file mode 100644
index 00000000..f071506a
--- /dev/null
+++ b/db/backup.go
@@ -0,0 +1,155 @@
+package db
+
+import (
+	"context"
+	"database/sql"
+	"fmt"
+	"os"
+	"path/filepath"
+	"runtime"
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/log"
+)
+
+const (
+	backupFilePrefix = "navidrome_backup_"
+	backupFileSuffix = ".db"
+	backupTimeFormat = "2006-01-02T15-04-05Z0700"
+)
+
+// Backup creates an online backup of the database in the configured backup path
+// (conf.Server.Backup.Path), returning the path of the created backup file.
+func (d *db) Backup(ctx context.Context) (string, error) {
+	backupDir := conf.Server.Backup.Path
+	if backupDir == "" {
+		return "", fmt.Errorf("backup path is not configured")
+	}
+	if err := os.MkdirAll(backupDir, os.ModePerm); err != nil {
+		return "", fmt.Errorf("error creating backup directory: %w", err)
+	}
+	backupFile := filepath.Join(backupDir, backupFileName())
+	if _, err := d.writeDB.ExecContext(ctx, fmt.Sprintf("VACUUM INTO '%s'", backupFile)); err != nil {
+		return "", fmt.Errorf("error creating backup: %w", err)
+	}
+	log.Info("Backup created", "file", backupFile)
+	return backupFile, nil
+}
+
+// Restore restores the database from the backup file located at path.
+func (d *db) Restore(ctx context.Context, path string) error {
+	log.Debug("Restoring database from backup", "path", path)
+
+	// Check the backup file exists
+	if _, err := os.Stat(path); err != nil {
+		return fmt.Errorf("backup file does not exist: %w", err)
+	}
+
+	// Open the backup file and check it is a valid database
+	backupDB, err := sql.Open(Driver, path)
+	if err != nil {
+		return fmt.Errorf("error opening backup file: %w", err)
+	}
+	defer backupDB.Close()
+	if _, err := backupDB.ExecContext(ctx, "SELECT 1 FROM sqlite_master LIMIT 1"); err != nil {
+		return fmt.Errorf("error reading backup file: %w", err)
+	}
+
+	// Close the current database connections
+	d.Close()
+
+	// For a file-based database, restore the contents into the current database file.
+	// For an in-memory database, the restored data lives in the backup file itself.
+	target := Path
+	if isMemoryDb(Path) {
+		target = path
+	} else {
+		// Remove the current database file, as VACUUM INTO cannot overwrite an existing file
+		if err := os.Remove(target); err != nil && !os.IsNotExist(err) {
+			return fmt.Errorf("error removing current database: %w", err)
+		}
+		if _, err := backupDB.ExecContext(ctx, fmt.Sprintf("VACUUM INTO '%s'", target)); err != nil {
+			return fmt.Errorf("error restoring database: %w", err)
+		}
+	}
+
+	// Reopen the database connections
+	if err := d.open(target); err != nil {
+		return err
+	}
+	log.Info("Database restored from backup", "file", path)
+	return nil
+}
+
+// Prune removes old backup files, keeping only the latest conf.Server.Backup.Count ones.
+// It returns the number of files removed.
+func (d *db) Prune(ctx context.Context) (int, error) {
+	return prune(ctx)
+}
+
+// prune removes old backup files from the configured backup path, keeping only the
+// latest conf.Server.Backup.Count files. It returns the number of files removed.
+func prune(ctx context.Context) (int, error) {
+	backupDir := conf.Server.Backup.Path
+	if backupDir == "" {
+		return 0, fmt.Errorf("backup path is not configured")
+	}
+	entries, err := os.ReadDir(backupDir)
+	if err != nil {
+		return 0, fmt.Errorf("error reading backup directory: %w", err)
+	}
+	var backupFiles []string
+	for _, entry := range entries {
+		if entry.IsDir() {
+			continue
+		}
+		name := entry.Name()
+		if strings.HasPrefix(name, backupFilePrefix) && strings.HasSuffix(name, backupFileSuffix) {
+			backupFiles = append(backupFiles, name)
+		}
+	}
+	// Sort by timestamp (filename) in descending order, so the oldest files come last
+	sort.Sort(sort.Reverse(sort.StringSlice(backupFiles)))
+	pruned := 0
+	for i, name := range backupFiles {
+		if i < conf.Server.Backup.Count {
+			continue
+		}
+		if err := os.Remove(filepath.Join(backupDir, name)); err != nil {
+			return pruned, fmt.Errorf("error removing backup file: %w", err)
+		}
+		log.Debug("Pruned backup file", "file", name)
+		pruned++
+	}
+	return pruned, nil
+}
+
+// open (re)opens the read and write database connections for the given path.
+func (d *db) open(path string) error {
+	rdb, err := sql.Open(Driver+"_custom", path)
+	if err != nil {
+		return fmt.Errorf("error opening read database: %w", err)
+	}
+	rdb.SetMaxOpenConns(max(4, runtime.NumCPU()))
+
+	wdb, err := sql.Open(Driver+"_custom", path)
+	if err != nil {
+		return fmt.Errorf("error opening write database: %w", err)
+	}
+	wdb.SetMaxOpenConns(1)
+
+	d.readDB = rdb
+	d.writeDB = wdb
+	return nil
+}
+
+func backupFileName() string {
+	return fmt.Sprintf("%s%s%s", backupFilePrefix, time.Now().Format(backupTimeFormat), backupFileSuffix)
+}
+
+func isMemoryDb(path string) bool {
+	return path == ":memory:" || strings.HasPrefix(path, "file::memory:")
+}
