+func validateLoginFromHeaders(userRepo model.UserRepository, userName string, r *http.Request) (*model.User, error) {
+	if !validateIPAgainstList(r, conf.Server.ReverseProxyWhitelist) {
+		return nil, nil
+	}
+	u, err := userRepo.FindByUsername(userName)
+	if err == model.ErrNotFound {
+		count, _ := userRepo.CountAll()
+		u = &model.User{
+			ID:          uuid.NewString(),
+			UserName:    userName,
+			Name:        strings.Title(userName),
+			IsAdmin:     count == 0, // first user is admin
+			NewPassword: uuid.NewString(),
+		}
+		err = userRepo.Put(u)
+		if err != nil {
+			log.Error("Could not create user", "user", userName, err)
+			return nil, err
+		}
+		u, err = userRepo.FindByUsername(userName)
+		if err != nil {
+			return nil, err
+		}
+	}
+	if err != nil {
+		return nil, err
+	}
