+// validateIPAgainstList checks if the IP address of the given request is in the
+// comma-separated list of CIDR ranges. The list can contain IPv4 and IPv6
+// ranges, and the special value "@" matches requests received over a Unix
+// socket. Invalid entries are ignored. An empty list matches nothing.
+func validateIPAgainstList(r *http.Request, whitelist string) bool {
+	if whitelist == "" {
+		return false
+	}
+	ip := r.RemoteAddr
+	if strings.Contains(ip, "@") {
+		// Unix socket
+		return strings.Contains(whitelist, "@")
+	}
+	for _, cidr := range strings.Split(whitelist, ",") {
+		cidr = strings.TrimSpace(cidr)
+		if cidr == "" {
+			continue
+		}
+		_, ipNet, err := net.ParseCIDR(cidr)
+		if err != nil {
+			log.Warn("Invalid CIDR in ReverseProxyWhitelist", "cidr", cidr)
+			continue
+		}
+		host, _, err := net.SplitHostPort(ip)
+		if err != nil {
+			host = ip
+		}
+		if ipNet.Contains(net.ParseIP(host)) {
+			return true
+		}
+	}
+	return false
 }

