+// CRLFWriter returns a writer that wraps w, converting LF ("\n") line
+// endings to CRLF ("\r\n") so that log output is correctly formatted on
+// Windows. Existing CRLF ("\r\n") sequences are preserved as-is, and it is
+// safe to use when the wrapped writer is written to in multiple steps.
+func CRLFWriter(w io.Writer) io.Writer {
+	return &crlfWriter{w: w}
+}
+
+type crlfWriter struct {
+	w   io.Writer
+	buf []byte // holds a trailing '\r' from a previous write
+}
+
+func (c *crlfWriter) Write(p []byte) (int, error) {
+	n := len(p)
+	var out []byte
+	// flush a '\r' buffered from the previous write
+	if len(c.buf) > 0 {
+		if len(p) > 0 && p[0] == '\n' {
+			// '\r' + '\n' already form CRLF, keep as-is
+			out = append(out, c.buf...)
+			out = append(out, '\n')
+			p = p[1:]
+		} else {
+			// standalone '\r', convert to CRLF
+			out = append(out, c.buf...)
+			out = append(out, '\n')
+		}
+		c.buf = nil
+	}
+	for i := 0; i < len(p); i++ {
+		switch b := p[i]; b {
+		case '\n':
+			out = append(out, '\r', '\n')
+		case '\r':
+			if i+1 < len(p) && p[i+1] == '\n' {
+				// existing CRLF, keep as-is
+				out = append(out, '\r', '\n')
+				i++
+			} else if i == len(p)-1 {
+				// '\r' at the end of this write, hold it until the next one
+				c.buf = append(c.buf, '\r')
+			} else {
+				// standalone '\r', convert to CRLF
+				out = append(out, '\r', '\n')
+			}
+		default:
+			out = append(out, b)
+		}
+	}
+	if len(out) > 0 {
+		if _, err := c.w.Write(out); err != nil {
+			return 0, err
+		}
+	}
+	return n, nil
+}
