+    // If date is not today, there is no min time because we want to display all intervals
+    if (!isToday(date)) {
+        return undefined;
+    }
+
+    // The expiration time must be at least 30 minutes in the future
+    const minExpiration = addMinutes(new Date(), 30);
+
+    // Round up to the next valid 30-minute interval (XX:00 or XX:30)
+    // so that the returned time is strictly later than the current time
+    const interval = new Date(minExpiration);
+    const minutes = interval.getMinutes();
+    const seconds = interval.getSeconds();
+    const milliseconds = interval.getMilliseconds();
+
+    if ((minutes === 0 || minutes === 30) && seconds === 0 && milliseconds === 0) {
+        // Already on a 30-minute boundary
+    } else if (minutes < 30) {
+        interval.setMinutes(30, 0, 0);
+    } else {
+        interval.setHours(interval.getHours() + 1, 0, 0, 0);
+    }
+
+    return interval;
+};

