@@ -0,0 +1,62 @@
+import { memo, useMemo } from 'react';
+
+import { c } from 'ttag';
+
+import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
+import { isProtonSender } from '../../helpers/elements';
+import { getElementSenders } from '../../helpers/recipients';
+import { useRecipientLabel } from '../../hooks/contact/useRecipientLabel';
+import { Element } from '../../models/element';
+import ProtonBadgeType, { PROTON_BADGE_TYPE } from './ProtonBadgeType';
+
+interface Props {
+    element: Element;
+    conversationMode: boolean;
+    loading: boolean;
+    unread: boolean;
+    displayRecipients: boolean;
+    isSelected: boolean;
+}
+
+/**
+ * Display the senders (or recipients) of an element in the mail list,
+ * along with the Proton badge when the sender (or recipient) is from Proton.
+ */
+const ItemSenders = ({ element, conversationMode, loading, unread, displayRecipients, isSelected }: Props) => {
+    const { shouldHighlight, highlightMetadata } = useEncryptedSearchContext();
+    const { getRecipientLabel, getRecipientsOrGroups } = useRecipientLabel();
+
+    const senders = getElementSenders(element, conversationMode, displayRecipients);
+
+    const sendersLabels = useMemo(() => senders.map((sender) => getRecipientLabel(sender, true)), [senders]);
+    const sendersAddresses = useMemo(() => senders.map((sender) => sender?.Address), [senders]);
+
+    const [firstSenderOrGroup] = getRecipientsOrGroups(senders) || [];
+    const isProton = isProtonSender(element, firstSenderOrGroup, displayRecipients);
+
+    const highlightData = shouldHighlight();
+    const sendersContent = useMemo(
+        () =>
+            !loading && displayRecipients && !senders.length
+                ? c('Info').t`(No Recipient)`
+                : highlightData
+                ? highlightMetadata(sendersLabels.join(', '), unread, true).resultJSX
+                : sendersLabels.join(', '),
+        [loading, displayRecipients, senders.length, highlightData, highlightMetadata, sendersLabels, unread]
+    );
+
+    return (
+        <span className="item-senders-name flex flex-nowrap">
+            {isProton && <ProtonBadgeType badgeType={PROTON_BADGE_TYPE.VERIFIED} selected={isSelected} />}
+            <span
+                className="max-w100 text-ellipsis"
+                title={sendersAddresses.join(', ')}
+                data-testid="item-senders"
+            >
+                {sendersContent}
+            </span>
+        </span>
+    );
+};
+
+export default memo(ItemSenders);
