+/**
+ * Check if an address is a Proton address
+ * @param address
+ */
+const isProtonAddress = (address: string | undefined) => {
+    if (!address) {
+        return false;
+    }
+    const [, domain] = address.split('@');
+    return PROTONMAIL_DOMAINS.includes((domain || '').toLowerCase());
+};
+
+/**
+ * Check if the sender of an element is from Proton.
+ * When displaying recipients (e.g. in sent or draft folders), check if the recipient is from Proton instead.
+ * @param element
+ * @param recipientOrGroup the recipient (or group of recipients) to check when displaying recipients
+ * @param displayRecipients
+ */
+export const isProtonSender = (
+    element: Element,
+    recipientOrGroup: RecipientOrGroup | undefined,
+    displayRecipients: boolean
+): boolean => {
+    if (displayRecipients) {
+        const recipients = recipientOrGroup?.recipient
+            ? [recipientOrGroup.recipient]
+            : recipientOrGroup?.group?.recipients || [];
+        return recipients.some((recipient) => isProtonAddress(recipient?.Address));
+    }
+    return !!element.IsProton;
+};
+
+/**
+ * @deprecated Use isProtonSender instead.
+ */
 export const isFromProton = (element: Element) => {
     return !!element.IsProton;
 };
