+import { Recipient } from '@proton/shared/lib/interfaces/Address';
+import { Message } from '@proton/shared/lib/interfaces/mail/Message';
+import { getRecipients as getMessageRecipients, getSender as getMessageSender } from '@proton/shared/lib/mail/messages';
+
+import { Conversation } from '../models/conversation';
+import { Element } from '../models/element';
+import { getRecipients as getConversationRecipients, getSenders as getConversationSenders } from './conversation';
+
+/**
+ * Get the senders of an element for display in the mail list.
+ * When `displayRecipients` is true (e.g. in sent or draft folders), the recipients are returned instead of the senders.
+ * @param element
+ * @param conversationMode
+ * @param displayRecipients
+ */
+export const getElementSenders = (
+    element: Element,
+    conversationMode: boolean,
+    displayRecipients: boolean
+): Recipient[] => {
+    if (conversationMode) {
+        return displayRecipients
+            ? getConversationRecipients(element as Conversation)
+            : getConversationSenders(element as Conversation);
+    }
+    const message = element as Message;
+    if (displayRecipients) {
+        return getMessageRecipients(message);
+    }
+    const sender = getMessageSender(message);
+    return sender ? [sender] : [];
+};

