+import type { DropdownSize, Unit } from './types';
+
+export enum DropdownSizeUnit {
+    Viewport = 'Viewport',
+    Static = 'Static',
+    Dynamic = 'Dynamic',
+    Anchor = 'Anchor',
+}
+
+const isUnit = (value: string | undefined): value is Unit =>
+    typeof value === 'string' && !Object.values(DropdownSizeUnit).includes(value as DropdownSizeUnit);
+
+export const getMaxSizeValue = (value: DropdownSize['maxWidth'] | Unit | undefined): string | undefined => {
+    if (value === DropdownSizeUnit.Viewport) {
+        return 'initial';
+    }
+    if (isUnit(value)) {
+        return value;
+    }
+    return undefined;
+};
+
+export const getWidthValue = (
+    width: DropdownSize['width'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined => {
+    if (width === DropdownSizeUnit.Anchor && anchorRect) {
+        return `${anchorRect.width}px`;
+    }
+    if (width === DropdownSizeUnit.Static && contentRect) {
+        return `${contentRect.width}px`;
+    }
+    if (isUnit(width)) {
+        return width;
+    }
+    return undefined;
+};
+
+export const getHeightValue = (
+    height: DropdownSize['height'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined => {
+    if (height === DropdownSizeUnit.Static && contentRect) {
+        return `${contentRect.height}px`;
+    }
+    if (isUnit(height)) {
+        return height;
+    }
+    return undefined;
+};
+
+export const getProp = (prop: string, value: string | undefined): Record<string, string> | undefined =>
+    value ? { [prop]: value } : undefined;
+
+export type { DropdownSize, Unit } from './types';
