+
+/**
+ * Removes all technical fields (i.e. fields starting with "_finalEncrypted", "_defaultEncrypted" or "_errors")
+ * from the given entity and from all objects nested inside it.
+ *
+ * The entity is modified in place. This is meant for new entities (e.g. freshly created or cloned ones)
+ * because the technical fields make the object unsuitable for update operations.
+ *
+ * @param entity The entity to remove the technical fields from. It is modified in place.
+ */
+export function removeTechnicalFields<E extends SomeEntity>(entity: E): void {
+	removeTechnicalFieldsFromObject(entity as unknown as Record<string, unknown>)
+}
+
+function removeTechnicalFieldsFromObject(obj: Record<string, unknown>): void {
+	for (const key of Object.keys(obj)) {
+		if (key.startsWith("_finalEncrypted") || key.startsWith("_defaultEncrypted") || key.startsWith("_errors")) {
+			delete obj[key]
+		} else {
+			const value = obj[key]
+			if (value != null && typeof value === "object") {
+				if (Array.isArray(value)) {
+					for (const item of value) {
+						if (item != null && typeof item === "object") {
+							removeTechnicalFieldsFromObject(item as Record<string, unknown>)
+						}
+					}
+				} else {
+					removeTechnicalFieldsFromObject(value as Record<string, unknown>)
+				}
+			}
+		}
+	}
+}

